function renderCampTab(tab){S._campTab=tab;document.querySelectorAll(".nav-tab").forEach(b=>b.classList.remove("active"));const btn=document.querySelector(`.nav-tab[data-tab="${tab}"]`);if(btn)btn.classList.add("active");document.querySelectorAll("#camp-view .tab-content").forEach(p=>p.classList.remove("active"));const panel=document.getElementById("tab-"+tab);if(panel)panel.classList.add("active");renderCamp()}
function renderPrep(){const eq=S.equipment,maxSlots=S.equipSlots;const allSlots={weapon:{label:"🗡 武器",side:"attack",desc:"攻击力·暴击",unlockAt:1},hands:{label:"✋ 手部",side:"attack",desc:"暴击率·攻速",unlockAt:2},relic:{label:"🔮 圣物",side:"attack",desc:"被动·复活",unlockAt:8},cloak:{label:"🧥 披风",side:"attack",desc:"火把·黑暗",unlockAt:7},head:{label:"🎩 头部",side:"defense",desc:"神智抗性",unlockAt:5},body:{label:"🛡 躯干",side:"defense",desc:"防御力·生命",unlockAt:1},waist:{label:"🎽 腰部",side:"defense",desc:"背包扩容",unlockAt:6},feet:{label:"👢 足部",side:"defense",desc:"闪避·移动",unlockAt:3}};const stats=calcHeroStats();const totalBag=S.bagCapacity+stats.bagSlots;const raceNames={human:"👤 人类",elf:"🧝 精灵",bear:"🐻 熊人",dwarf:"⛏️ 矮人"};function slotHTML(key){const cfg=allSlots[key];const locked=maxSlots<cfg.unlockAt;const lockHints={5:"到达中层甬道解锁",6:"到达中层甬道解锁",7:"到达深层墓室解锁",8:"到达绝渊回廊解锁"};const item=eq[key];if(locked)return `<div class="equip-slot" style="opacity:0.4"><span class="slot-label">${cfg.label}</span><span class="slot-empty">🔒 ${lockHints[cfg.unlockAt]||"未解锁"}</span></div>`;if(item){const durPct=item.maxDurability>0?Math.round(item.durability/item.maxDurability*100):100;const warnClass=durPct<25?"durability-warn":"";return `<div class="equip-slot ${warnClass}"><div><span class="slot-label">${cfg.label}</span><span style="font-size:9px;color:var(--muted);"> ${cfg.desc}</span><br><span class="slot-item ${'rarity-'+item.rarity}">${item.name}</span><span style="font-size:10px;color:${durPct<25?'var(--blood-bright)':'var(--muted)'};"> 耐久 ${Math.round(item.durability)}/${item.maxDurability}</span></div><div class="slot-actions">${item.durability<item.maxDurability?`<button class="small" onclick="repairEquipment('${key}');event.stopPropagation();">修 ${repairCost(item)}金</button>`:""}<button class="small danger" onclick="unequipItem('${key}');event.stopPropagation();">卸</button></div></div>`}return `<div class="equip-slot"><span class="slot-label">${cfg.label}</span><span style="font-size:9px;color:var(--muted);"> ${cfg.desc}</span><span class="slot-empty">空</span></div>`}const attackSlots=["weapon","hands","relic","cloak"];const defenseSlots=["head","body","waist","feet"];el("equipSlots").innerHTML=`<div style="font-size:12px;color:var(--candle-dim);margin-bottom:8px;">种族：${raceNames[S.hero.race]||"👤 人类"}</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;"><div><div style="text-align:center;font-size:11px;color:var(--candle-dim);letter-spacing:0.15em;margin-bottom:6px;border-bottom:1px solid var(--line);padding-bottom:4px;">— 攻 势 —</div>${attackSlots.map(k=>slotHTML(k)).join("")}</div><div><div style="text-align:center;font-size:11px;color:var(--candle-dim);letter-spacing:0.15em;margin-bottom:6px;border-bottom:1px solid var(--line);padding-bottom:4px;">— 守 御 —</div>${defenseSlots.map(k=>slotHTML(k)).join("")}</div></div>`;const inv=S.inventory;el("invCount").textContent=inv.length+"/"+totalBag;if(inv.length===0)el("invPanel").innerHTML=`<div style="color:var(--muted);font-size:12px;text-align:center;padding:20px;">背包空空如也<br><span style="font-size:10px;">深入深渊，获取战利品</span></div>`;else el("invPanel").innerHTML=inv.map((item,i)=>{const canEquip=!item.unidentified&&item.type!=="material"&&maxSlots>=(allSlots[item.type]?allSlots[item.type].unlockAt:99);const durText=item.type!=="material"?`<span class="inv-dur">${Math.round(item.durability)}/${item.maxDurability}</span>`:"";return `<div class="inv-row"><span class="inv-name ${'rarity-'+item.rarity}">${item.unidentified?'🔍 ':''}${item.name}</span>${durText}<span class="inv-act">${canEquip?`<button class="small" onclick="equipFromInv(${i})">装备</button>`:""}<button class="small" style="border-color:var(--candle);color:var(--candle);" onclick="sellItem(${i})">出售 ${item.sellPrice}金</button><button class="small danger" onclick="discardItem(${i})">丢弃</button></span></div>`}).join("")}
function renderQuestBoard(){checkQuestCompletion();const now=Date.now();if(S.activeQuests.length<3&&(!S.questRefreshAt||now>=S.questRefreshAt)){refreshQuests();S.questRefreshAt=now+2*60*1000}let html="";S.activeQuests.forEach((q,idx)=>{const remaining=q.expiresAt?Math.max(0,Math.floor((q.expiresAt-now)/1000)):0;const min=Math.floor(remaining/60),sec=remaining%60;const urgent=remaining<120;const cardClass=q.completed?"completed":(remaining<=0?"failed":"");html+=`<div class="quest-card ${cardClass}"><div class="q-header"><span class="q-name">${q.completed?'✅ ':''}${q.name}</span><span class="q-timer ${urgent?'urgent':'normal'}">⏱ ${min}:${sec.toString().padStart(2,'0')}</span></div><div class="q-desc">${q.desc}</div><div class="q-progress">进度：${q.progress||0}/${q.count||1}${q.type==='survive'?' 分钟':''}</div><div class="q-reward">🎁 ${q.reward.gold}金${q.reward.itemTid?' + '+getEquipName(q.reward.itemTid):''}</div><div class="q-actions">${q.completed?`<button class="primary small" onclick="claimQuestById(${idx})">领取奖励</button>`:`<button class="small danger" onclick="abandonQuest(${idx})">放弃</button>`}</div></div>`});if(S.activeQuests.length===0)html=`<div style="color:var(--muted);text-align:center;padding:20px;">暂无悬赏令<br><span style="font-size:10px;">等待任务板刷新……</span></div>`;el("questList").innerHTML=html;const secToRefresh=S.questRefreshAt?Math.max(0,Math.floor((S.questRefreshAt-now)/1000)):0;el("questRefreshInfo").textContent=`刷新倒计时: ${Math.floor(secToRefresh/60)}:${(secToRefresh%60).toString().padStart(2,'0')}`}
function renderShop(){let html="";SHOP_ITEMS.forEach(item=>{const held=S.expedition.consumables[item.id]||0;const canBuy=!S.expedition.active&&S.gold>=item.price&&held<item.maxCarry;html+=`<div class="shop-card" style="flex:1;min-width:140px;background:var(--panel-2);border:1px solid var(--line);border-radius:3px;padding:12px;text-align:center;"><div style="font-size:22px;">${item.icon}</div><div style="font-size:14px;color:var(--moon);margin:4px 0;">${item.name}</div><div style="font-size:10px;color:var(--muted);margin-bottom:6px;">${item.desc}</div><div style="font-size:10px;color:var(--muted);margin-bottom:6px;">携带: ${held}/${item.maxCarry}</div><button class="small primary" ${!canBuy?'disabled':''} onclick="buyConsumable('${item.id}')">${item.price}金</button></div>`});el("shopItems").innerHTML=html}
function renderSmith(subtab){S._smithTab=subtab;document.querySelectorAll(".smith-tab").forEach(b=>b.classList.remove("active"));const btn=document.querySelector(`.smith-tab[data-smith="${subtab}"]`);if(btn)btn.classList.add("active");document.querySelectorAll(".smith-content").forEach(p=>p.classList.remove("active"));const panel=document.getElementById("smith-"+subtab);if(panel)panel.classList.add("active");el("identifyBadge").textContent=S.inventory.filter(i=>i.unidentified).length>0?`(${S.inventory.filter(i=>i.unidentified).length})`:"";const smithMul=S.hero.race==="dwarf"?0.7:1;let sellHtml="";if(S.inventory.length===0)sellHtml=`<div style="color:var(--muted);text-align:center;padding:20px;">没有可出售的物品</div>`;else S.inventory.forEach((item,i)=>{sellHtml+=`<div class="sell-row"><span class="${'rarity-'+item.rarity}">${item.unidentified?'🔍 ':''}${item.name} ${item.type!=="material"?`[${Math.round(item.durability)}/${item.maxDurability}]`:''}</span><span class="sell-price">${item.sellPrice}金</span><button class="small" style="border-color:var(--candle);color:var(--candle);" onclick="sellItem(${i})">出售</button></div>`});el("smith-sell").innerHTML=sellHtml;let idHtml="";const unidItems=S.inventory.filter(i=>i.unidentified);if(unidItems.length===0)idHtml=`<div style="color:var(--muted);text-align:center;padding:20px;">没有待鉴定的物品<br><span style="font-size:10px;">深渊中偶尔能发现需要鉴定的装备</span></div>`;else unidItems.forEach(item=>{const cost=Math.round((item.sellPrice||10)*0.4*smithMul);idHtml+=`<div class="sell-row"><span>🔍 ${item.name}</span><span class="sell-price">鉴定费 ${cost}金</span><button class="small primary" onclick="identifyItem('${item.id}')">鉴定</button></div>`});el("smith-identify").innerHTML=idHtml;let craftHtml=`<table class="craft-table"><tr><th>名称</th><th>类型</th><th>稀有度</th><th>材料</th><th>金币</th><th></th></tr>`;CRAFT_RECIPES.forEach(recipe=>{const locked=!S.unlockedLayers.includes(recipe.needLayer);const resultTpl=EQUIP_TEMPLATES.find(e=>e.id===recipe.result.tid);const name=resultTpl?resultTpl.name:recipe.name;const rarity=resultTpl?resultTpl.rarity:"common";const type=resultTpl?resultTpl.type:"?";const matsText=recipe.materials.map(m=>`${getMaterialName(m.mid)}×${m.qty}`).join(" + ");const craftCost=Math.round(recipe.cost*smithMul);const canCraft=!locked&&recipe.materials.every(m=>countMaterial(m.mid)>=m.qty)&&S.gold>=craftCost&&S.inventory.length<getBagCapacity();craftHtml+=`<tr class="${locked?'locked-row':''}"><td class="${'rarity-'+rarity}">${name}</td><td>${slotLabel(type)}</td><td>${RARITY[rarity]?RARITY[rarity].name:'?'}</td><td>${matsText}</td><td>${craftCost}金${smithMul<1?' (-30%)':''}</td><td>${locked?`<span style="font-size:10px;color:var(--muted);">需要${LAYERS[recipe.needLayer].name}</span>`:`<button class="small primary" ${!canCraft?'disabled':''} onclick="craftItem('${recipe.id}')">打造</button>`}</td></tr>`});craftHtml+=`</table>`;el("smith-craft").innerHTML=craftHtml}
function renderAbyssGate(){let html="";LAYERS.forEach((layer,i)=>{const unlocked=S.unlockedLayers.includes(i);const selected=S.selectedLayer===i;html+=`<div class="layer-card ${unlocked?'':'locked'} ${selected?'selected':''}" ${unlocked?`onclick="selectLayer(${i})"`:''}><div class="l-name">${unlocked?'🔓':'🔒'} ${layer.name}</div><div class="l-depth">${layer.startDepth} - ${layer.maxDepth>=999?'∞':layer.maxDepth} 尺</div><div class="l-monsters">🐉 ${layer.monsters.slice(0,3).join(' · ')}${layer.monsters.length>3?' …':''}</div><div class="l-danger">危险等级：${layer.danger}</div>${!unlocked?`<div class="l-unlock">${layer.unlockMsg||'?'}</div>`:''}${layer.unlockBonus?`<div class="l-unlock" style="color:var(--candle-dim);">${layer.unlockBonus}</div>`:''}</div>`});el("layerCards").innerHTML=html;const layer=LAYERS[S.selectedLayer];const unlocked=S.unlockedLayers.includes(S.selectedLayer);el("abyssAction").innerHTML=unlocked?`<button class="primary" style="font-size:16px;padding:12px 40px;" onclick="startExpedition(${S.selectedLayer})">⚔️ 从「${layer.name}」出征</button>`:`<span style="color:var(--muted);">该层级尚未解锁</span>`}
function renderChurch(){const now=Date.now();const onCooldown=S.prayerCooldown>now;const remaining=onCooldown?S.prayerCooldown-now:0;const hrs=Math.floor(remaining/3600000);const mins=Math.floor((remaining%3600000)/60000);if(S.activeBlessing){el("churchStatus").innerHTML=`<span style="color:var(--candle);">当前祝福生效中：</span>`;el("churchBuff").innerHTML=`<span style="font-size:18px;">${S.activeBlessing.icon} <strong style="color:var(--candle);">${S.activeBlessing.name}</strong></span><br><span style="font-size:12px;color:var(--muted);">${S.activeBlessing.desc}（下次远征生效）</span>`;el("prayBtn").disabled=true;el("prayBtn").textContent="祝福已就绪，出征吧"}else if(onCooldown){el("churchStatus").innerHTML=`<span style="color:var(--muted);">祷告后需静候神明的回应……</span>`;el("churchBuff").innerHTML=`<span style="font-size:13px;color:var(--muted);">冷却剩余：</span><span style="font-size:16px;color:var(--sanity);">${hrs}时${mins}分</span>`;el("prayBtn").disabled=true;el("prayBtn").textContent=`⏳ ${hrs}时${mins}分后可祈祷`}else{el("churchStatus").innerHTML=`<span style="color:var(--muted);">在深渊礼拜堂中静心祈祷，祈求神明的眷顾。</span>`;el("churchBuff").innerHTML=`<span style="font-size:12px;color:var(--muted);">可能获得的祝福：</span><br><span style="font-size:11px;color:var(--muted);">${BLESSINGS.map(b=>b.icon+b.name).join(' · ')}</span>`;el("prayBtn").disabled=false;el("prayBtn").textContent="🕯️ 祈 祷"}const s=calcHeroStats();const effMax=S.hero.maxSanity+s.maxSanityBonus;const cost=Math.ceil((effMax-S.hero.sanity)*1.5);const canRestore=S.hero.sanity<effMax&&S.gold>=cost;el("churchRestore").innerHTML=`<span style="font-size:12px;color:var(--muted);">恢复神智 · ${S.hero.sanity>=effMax?'神智已满':cost+' 金'}</span>`;const rstBtn=document.getElementById("restoreSanityBtn");if(rstBtn){rstBtn.disabled=!canRestore;rstBtn.textContent=S.hero.sanity>=effMax?"🙏 神智已满":`🙏 静心祈祷 · ${cost}金`}}
function doPray(){if(S.prayerCooldown>Date.now()||S.activeBlessing)return;const b=BLESSINGS[Math.floor(Math.random()*BLESSINGS.length)];S.activeBlessing={type:b.id,name:b.name,desc:b.desc,icon:b.icon,apply:b.apply};S.prayerCooldown=Date.now()+3*60*60*1000;pushLog(`⛪ 你在礼拜堂中虔诚祈祷，获得了「${b.name}」——${b.desc}`,"good");render();save()}
function restoreSanity(){const s=calcHeroStats();const effMax=S.hero.maxSanity+s.maxSanityBonus;const cost=Math.ceil((effMax-S.hero.sanity)*1.5);if(S.hero.sanity>=effMax||S.gold<cost)return;S.gold-=cost;S.hero.sanity=effMax;pushLog("你在残烛前静坐良久，心神渐渐安定。","good");render();save()}

function warehouseUpgradeCost(){const level=(S.warehouseSlots-20)/5;return Math.round(100*Math.pow(1.5,level))}
function upgradeWarehouse(){if(S.warehouseSlots>=50)return;const cost=warehouseUpgradeCost();if(S.gold<cost)return;S.gold-=cost;S.warehouseSlots+=5;pushLog(`📦 秘库扩容至 ${S.warehouseSlots} 格，花费 ${cost} 金。`,"good");render();save()}
function depositItem(idx){const item=S.inventory[idx];if(!item||item.unidentified||S.warehouse.length>=S.warehouseSlots)return;if(item.type==="material"&&item.templateId){const existing=S.warehouse.find(w=>w.templateId===item.templateId);if(existing&&existing.qty!==undefined){existing.qty+=1;S.inventory.splice(idx,1);render();save();return}S.warehouse.push({...item,qty:1})}else S.warehouse.push(item);S.inventory.splice(idx,1);render();save()}
function withdrawItem(whIdx){const item=S.warehouse[whIdx];if(!item||S.inventory.length>=getBagCapacity())return;if(item.qty!==undefined&&item.qty>1){const single={...item};delete single.qty;S.inventory.push(single);item.qty-=1;if(item.qty<=0)S.warehouse.splice(whIdx,1)}else{S.inventory.push(item);S.warehouse.splice(whIdx,1)}render();save()}
