function renderWarehouse(){const wh=S.warehouse,inv=S.inventory;el("whCount").textContent=wh.length+"/"+S.warehouseSlots;if(S.warehouseSlots>=50)el("whUpgradeRow").innerHTML=`<span style="font-size:11px;color:var(--candle-dim);">秘库已满级 (50格)</span>`;else{const cost=warehouseUpgradeCost();el("whUpgradeRow").innerHTML=`<button class="small" ${S.gold<cost?'disabled':''} onclick="upgradeWarehouse()">扩容 +5格 · ${cost}金</button>`}if(wh.length===0)el("whPanel").innerHTML=`<div style="color:var(--muted);font-size:11px;text-align:center;padding:16px;">仓库空空如也</div>`;else el("whPanel").innerHTML=wh.map((item,i)=>{const name=item.name+(item.qty>1?` ×${item.qty}`:"");const sub=item.type!=="material"?`<span class="inv-dur">${Math.round(item.durability)}/${item.maxDurability}</span>`:"";return `<div class="inv-row"><span class="inv-name ${'rarity-'+item.rarity}">${name}</span>${sub}<span class="inv-act"><button class="small" onclick="withdrawItem(${i})">取出</button></span></div>`}).join("");if(inv.length===0)el("whInvPanel").innerHTML=`<div style="color:var(--muted);font-size:11px;text-align:center;padding:12px;">背包空空如也</div>`;else el("whInvPanel").innerHTML=inv.map((item,i)=>{const canDeposit=!item.unidentified&&wh.length<S.warehouseSlots;return `<div class="inv-row"><span class="inv-name ${'rarity-'+item.rarity}">${item.unidentified?'🔍 ':''}${item.name}</span><span class="inv-dur">${item.type!=="material"?Math.round(item.durability)+'/'+item.maxDurability:''}</span><span class="inv-act"><button class="small" ${!canDeposit?'disabled':''} onclick="depositItem(${i})">${item.unidentified?'🔍鉴定后':'存入'}</button></span></div>`}).join("")}

function confirmDeleteSave(){showModal("确认删除存档","此操作将永久删除你的所有进度，包括金币、装备、怪物志和最深记录。此操作不可撤销。",[{label:"取消",cls:"",action:"hideModal()"},{label:"确认删除",cls:"danger",action:"deleteSave()"}])}
function deleteSave(){S._deleting=true;localStorage.removeItem(SAVE_KEY);hideModal();location.reload()}
function renderSettings(){const el2=document.getElementById("settingsStats");if(el2)el2.innerHTML=`最深记录：<span style="color:var(--candle);">${S.maxDepthRecord.toFixed(1)}</span> 尺<br>持有金币：<span style="color:var(--candle);">${S.gold}</span><br>怪物志：<span style="color:var(--candle);">${Object.keys(S.bestiary).length}</span> 种<br>遗物收集：<span style="color:var(--candle);">${Object.keys(S.relicsOwned).length}</span> / ${RELICS.length}<br>最深层级：<span style="color:var(--candle);">${S.unlockedLayers.length>0?LAYERS[Math.max(...S.unlockedLayers)].name:'浅层回廊'}</span><br>当前种族：<span style="color:var(--candle);">${({human:'👤 人类',elf:'🧝 精灵',bear:'🐻 熊人',dwarf:'⛏️ 矮人'})[S.hero.race]||'???'}</span>`}
function renderTavern(){el("tavernRecord").textContent=S.maxDepthRecord.toFixed(1)}
function renderExpedition(){const ex=S.expedition,stats=calcHeroStats(),h=S.hero;const raceNames={human:"👤 人类",elf:"🧝 精灵",bear:"🐻 熊人",dwarf:"⛏️ 矮人"};el("expRace").textContent=raceNames[h.race]||"👤 人类";el("expLayerName").textContent=LAYERS[ex.layerIndex]?LAYERS[ex.layerIndex].name:"???";el("expCarriedGold").textContent=ex.carriedGold||0;el("hpNum").textContent=`${Math.max(0,Math.round(h.hp))} / ${stats.maxHp}`;el("hpFill").style.width=Math.max(0,(h.hp/stats.maxHp*100))+"%";el("atkNum").textContent=stats.atk;el("defNum").textContent=stats.def;el("dodgeNum").textContent=Math.round(stats.dodge*100)+"%";el("sanityNum").textContent=Math.round(h.sanity)+"/"+(h.maxSanity+stats.maxSanityBonus);el("sanityFill").style.width=(h.sanity/(h.maxSanity+stats.maxSanityBonus)*100)+"%";el("goldNumH").textContent=S.gold;el("depthNum").textContent=ex.depth.toFixed(1);el("recordNum").textContent=S.maxDepthRecord.toFixed(1);const torchPct=ex.active?Math.max(0,ex.torch/ex.maxTorch*100):100;el("torchFill").style.height=torchPct+"%";el("torchPct").textContent=Math.round(torchPct);const flame=el("flame");flame.style.animationDuration=ex.active?(0.6+torchPct/100*1.2)+"s":"1.6s";flame.style.opacity=ex.active?(0.4+torchPct/100*0.6):1;el("expLayerLabel").textContent=LAYERS[ex.layerIndex]?LAYERS[ex.layerIndex].name:"???";el("expDepthMax").textContent=LAYERS[ex.layerIndex]?LAYERS[ex.layerIndex].maxDepth+"尺":"?";if(ex.itemsFound.length===0)el("expItemsBag").innerHTML=`<div style="color:var(--muted);font-size:10px;text-align:center;">暂无战利品</div>`;else el("expItemsBag").innerHTML=ex.itemsFound.map(item=>`<div class="row"><span class="${'rarity-'+item.rarity}">${item.name}</span></div>`).join("");const box=el("encounterBox");if(!ex.active){box.className="encounter empty";box.innerHTML="远征结束"}else if(!ex.monster){if(ex.event&&ex.event.type!=="narrative"){const ev=ex.event;box.className="encounter";box.innerHTML=`<div style="font-size:15px;color:var(--candle);margin-bottom:8px;">${ev.name||"……"}</div><div style="font-size:12px;color:var(--muted);margin-bottom:12px;">${ev.type==="curio"?"一件奇物出现在你面前。":ev.type==="trap"?"前方有危险的气息。":"一处可以歇脚的地方。"}</div><div style="display:flex;gap:8px;"><button class="small" onclick="resolveEvent('safe')" style="flex:1;">${ev.safe.text||"稳妥行事"}</button><button class="small danger" onclick="resolveEvent('risky')" style="flex:1;">${ev.risky.text||"冒险一试"}</button></div>`}else{box.className="encounter empty";box.innerHTML="回廊寂静无声…"}}else{box.className="encounter";const pct=Math.max(0,ex.monster.hp/ex.monster.maxHp*100);box.innerHTML=`<div class="monster-name">${ex.monster.name}</div><div class="monster-hp-wrap"><div class="monster-hp"><div style="width:${pct}%"></div></div><div class="monster-hp-num">${Math.max(0,Math.round(ex.monster.hp))}/${ex.monster.maxHp}</div></div>`}el("descendBtn").disabled=ex.active;el("retreatBtn").disabled=!ex.active;el("logBox").innerHTML=S.logs.map(l=>`<div class="entry ${l.cls}">${l.text}</div>`).join("");const skillBar=document.getElementById("skillBar");if(skillBar){const bloodrageBlock=h.race==="bear"&&h.sanity<h.maxSanity*0.3;const allSkills=[...SKILLS.filter(s=>!s.race||s.race===h.race)];skillBar.innerHTML=allSkills.map(sk=>{const onCd=ex.skillCooldowns[sk.id]&&ex.skillCooldowns[sk.id]>0;const cdText=onCd?` (${ex.skillCooldowns[sk.id]}s)`:"";let disabled=!ex.active||!ex.monster||bloodrageBlock;if(ex.active&&ex.monster&&!onCd&&!bloodrageBlock){if(sk.costType==="sanity"&&h.sanity<sk.cost)disabled=true;if(sk.costType==="torch"&&ex.torch<sk.cost)disabled=true;if(sk.costType==="hp"&&h.hp<=sk.cost)disabled=true}let cls="skill-btn";if(onCd)cls+=" on-cooldown";const hasBuff=ex.activeBuffs[sk.buffKey];if(hasBuff)cls+=" active-buff";if(sk.id==="allin")cls+=" danger";const text=onCd?sk.name+cdText:sk.name;return `<button class="${cls}" ${disabled?'disabled':''} onclick="useSkill('${sk.id}')">${sk.name}</button>`}).join("")}const consumableBar=document.getElementById("consumableBar");if(consumableBar){const inCombat=ex.active&&ex.monster;consumableBar.innerHTML=SHOP_ITEMS.map(item=>{const held=ex.consumables[item.id]||0;const combatOnly=(item.effect==="holyWater"||item.effect==="firebomb");const canUse=ex.active&&held>0&&(!combatOnly||inCombat);return `<button class="skill-btn" ${!canUse?'disabled':''} onclick="useConsumable('${item.id}')" title="${item.desc} (剩余 ${held})">${item.icon} ${held}</button>`}).join("")}document.getElementById("headerEyebrow").textContent="深 渊 · 探 索 · 生 存";document.getElementById("headerSub").textContent="火光摇曳，深渊在等待"}
function equipFromInv(idx){const item=S.inventory[idx];if(!item||item.unidentified||item.type==="material")return;const slotKey=item.type;if(!S.equipment.hasOwnProperty(slotKey))return;const unlockMap={weapon:1,body:1,hands:2,feet:3,head:5,waist:6,cloak:7,relic:8};if(S.equipSlots<(unlockMap[slotKey]||1))return;const old=S.equipment[slotKey];S.equipment[slotKey]=item;if(old){if(S.inventory.length>=getBagCapacity()){S.gold+=Math.floor(old.sellPrice||1);pushLog(`背包已满，换下的${old.name}自动出售。`,"dim")}else{S.inventory.splice(idx,1,old);pushLog(`将${old.name}换为${item.name}。`,"dim")}}else{S.inventory.splice(idx,1);pushLog(`装备了${item.name}。`,"dim")}render();save()}
function unequipItem(slotKey){const item=S.equipment[slotKey];if(!item)return;if(S.inventory.length>=getBagCapacity()){S.gold+=Math.floor(item.sellPrice||1);S.equipment[slotKey]=null;pushLog(`背包已满，卸下${item.name}后自动出售，获得 ${Math.floor(item.sellPrice||1)} 金。`,"dim")}else{S.inventory.push(item);S.equipment[slotKey]=null;pushLog(`卸下了${item.name}。`,"dim")}render();save()}
function repairEquipment(slotKey){const item=S.equipment[slotKey];const cost=repairCost(item);if(cost<=0||S.gold<cost)return;S.gold-=cost;item.durability=item.maxDurability;pushLog(`修复了${item.name}，花费 ${cost} 金。`,"dim");render();save()}
function sellItem(idx){const item=S.inventory[idx];if(!item)return;S.gold+=item.sellPrice||1;pushLog(`出售了${item.name}，获得 ${item.sellPrice||1} 金。`,"dim");S.inventory.splice(idx,1);render();save()}
function discardItem(idx){S.inventory.splice(idx,1);pushLog("丢弃了一件物品。","dim");render();save()}
function identifyItem(itemId){const item=S.inventory.find(i=>i.id===itemId);if(!item||!item.unidentified)return;const smithMul=S.hero.race==="dwarf"?0.7:1;const cost=Math.round((item.sellPrice||10)*0.4*smithMul);if(S.gold<cost){pushLog("金币不足，无法鉴定。","warn");render();save();return}S.gold-=cost;item.unidentified=false;if(item.templateId){const tpl=EQUIP_TEMPLATES.find(e=>e.id===item.templateId);if(tpl)item.name=tpl.name}pushLog(`鉴定完成——是「${item.name}」！`,"good");render();save()}
function claimQuest(q){if(!q.completed)return;S.gold+=q.reward.gold;pushLog(`完成任务「${q.name}」，获得 ${q.reward.gold} 金。`,"good");if(q.reward.itemTid){const tpl=EQUIP_TEMPLATES.find(e=>e.id===q.reward.itemTid);if(tpl&&S.inventory.length<getBagCapacity()){const item={id:tpl.id+"_quest_"+Date.now()+"_"+Math.random().toString(36).slice(2,6),templateId:tpl.id,name:tpl.name,type:tpl.type,rarity:tpl.rarity,stats:{...tpl.baseStats},durability:tpl.baseDura,maxDurability:tpl.baseDura,sellPrice:tpl.baseVal,unidentified:false};S.inventory.push(item);pushLog(`获得了 ${tpl.name}！`,"good")}}S.completedQuestIds.push(q.poolId);S.activeQuests=S.activeQuests.filter(aq=>aq!==q);S.questRefreshAt=Date.now()+2*60*1000}
function refreshQuests(){if(S.activeQuests.length>=3)return;const need=3-S.activeQuests.length;for(let i=0;i<need;i++){const q=generateQuest();if(q)S.activeQuests.push(q)}}

function switchToCamp(){document.body.classList.remove("in-expedition");renderCampTab(S._campTab||"prep")}
function switchToExpedition(){document.body.classList.add("in-expedition")}

function repairCost(item){if(!item||item.durability>=item.maxDurability)return 0;const rarityData=RARITY[item.rarity]||RARITY.common;const missing=item.maxDurability-item.durability;return Math.max(1,Math.round(missing*0.02*(item.sellPrice||5)*rarityData.craftCostMul))}

function render(){if(document.body.classList.contains("in-expedition"))renderExpedition();else renderCamp()}
function renderCamp(){el("goldNumH").textContent=S.gold;const tab=S._campTab||"prep";renderPrep();renderQuestBoard();renderShop();renderSmith(tab==="smith"?S._smithTab||"sell":"sell");renderAbyssGate();renderChurch();renderWarehouse();renderSettings();renderTavern();document.getElementById("headerEyebrow").textContent="营 地 · 整 备 · 出 征";document.getElementById("headerSub").textContent="火尽人归，深处不留光"}
function renderCampTab(tab){S._campTab=tab;document.querySelectorAll(".nav-tab").forEach(b=>b.classList.remove("active"));const btn=document.querySelector(`.nav-tab[data-tab="${tab}"]`);if(btn)btn.classList.add("active");document.querySelectorAll("#camp-view .tab-content").forEach(p=>p.classList.remove("active"));const panel=document.getElementById("tab-"+tab);if(panel)panel.classList.add("active");renderCamp()}

function renderPrep(){const eq=S.equipment,maxSlots=S.equipSlots;const allSlots={weapon:{label:"🗡 武器",side:"attack",desc:"攻击力·暴击",unlockAt:1},hands:{label:"✋ 手部",side:"attack",desc:"暴击率·攻速",unlockAt:2},relic:{label:"🔮 圣物",side:"attack",desc:"被动·复活",unlockAt:8},cloak:{label:"🧥 披风",side:"attack",desc:"火把·黑暗",unlockAt:7},head:{label:"🎩 头部",side:"defense",desc:"神智抗性",unlockAt:5},body:{label:"🛡 躯干",side:"defense",desc:"防御力·生命",unlockAt:1},waist:{label:"🎽 腰部",side:"defense",desc:"背包扩容",unlockAt:6},feet:{label:"👢 足部",side:"defense",desc:"闪避·移动",unlockAt:3}};const stats=calcHeroStats();const totalBag=S.bagCapacity+stats.bagSlots;const raceNames={human:"👤 人类",elf:"🧝 精灵",bear:"🐻 熊人",dwarf:"⛏️ 矮人"};function slotHTML(key){const cfg=allSlots[key];const locked=maxSlots<cfg.unlockAt;const lockHints={5:"到达中层甬道解锁",6:"到达中层甬道解锁",7:"到达深层墓室解锁",8:"到达绝渊回廊解锁"};const item=eq[key];if(locked)return `<div class="equip-slot" style="opacity:0.4"><span class="slot-label">${cfg.label}</span><span class="slot-empty">🔒 ${lockHints[cfg.unlockAt]||"未解锁"}</span></div>`;if(item){const durPct=item.maxDurability>0?Math.round(item.durability/item.maxDurability*100):100;const warnClass=durPct<25?"durability-warn":"";return `<div class="equip-slot ${warnClass}"><div><span class="slot-label">${cfg.label}</span><span style="font-size:9px;color:var(--muted);"> ${cfg.desc}</span><br><span class="slot-item ${'rarity-'+item.rarity}">${item.name}</span><span style="font-size:10px;color:${durPct<25?'var(--blood-bright)':'var(--muted)'};"> 耐久 ${Math.round(item.durability)}/${item.maxDurability}</span></div><div class="slot-actions">${item.durability<item.maxDurability?`<button class="small" onclick="repairEquipment('${key}');event.stopPropagation();">修 ${repairCost(item)}金</button>`:""}<button class="small danger" onclick="unequipItem('${key}');event.stopPropagation();">卸</button></div></div>`}return `<div class="equip-slot"><span class="slot-label">${cfg.label}</span><span style="font-size:9px;color:var(--muted);"> ${cfg.desc}</span><span class="slot-empty">空</span></div>`}const attackSlots=["weapon","hands","relic","cloak"];const defenseSlots=["head","body","waist","feet"];el("equipSlots").innerHTML=`<div style="font-size:12px;color:var(--candle-dim);margin-bottom:8px;">种族：${raceNames[S.hero.race]||"👤 人类"}</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;"><div><div style="text-align:center;font-size:11px;color:var(--candle-dim);letter-spacing:0.15em;margin-bottom:6px;border-bottom:1px solid var(--line);padding-bottom:4px;">— 攻 势 —</div>${attackSlots.map(k=>slotHTML(k)).join("")}</div><div><div style="text-align:center;font-size:11px;color:var(--candle-dim);letter-spacing:0.15em;margin-bottom:6px;border-bottom:1px solid var(--line);padding-bottom:4px;">— 守 御 —</div>${defenseSlots.map(k=>slotHTML(k)).join("")}</div></div>`;const inv=S.inventory;el("invCount").textContent=inv.length+"/"+totalBag;if(inv.length===0)el("invPanel").innerHTML=`<div style="color:var(--muted);font-size:12px;text-align:center;padding:20px;">背包空空如也<br><span style="font-size:10px;">深入深渊，获取战利品</span></div>`;else el("invPanel").innerHTML=inv.map((item,i)=>{const canEquip=!item.unidentified&&item.type!=="material"&&maxSlots>=(allSlots[item.type]?allSlots[item.type].unlockAt:99);const durText=item.type!=="material"?`<span class="inv-dur">${Math.round(item.durability)}/${item.maxDurability}</span>`:"";return `<div class="inv-row"><span class="inv-name ${'rarity-'+item.rarity}">${item.unidentified?'🔍 ':''}${item.name}</span>${durText}<span class="inv-act">${canEquip?`<button class="small" onclick="equipFromInv(${i})">装备</button>`:""}<button class="small" style="border-color:var(--candle);color:var(--candle);" onclick="sellItem(${i})">出售 ${item.sellPrice}金</button><button class="small danger" onclick="discardItem(${i})">丢弃</button></span></div>`}).join("")}

function renderQuestBoard(){checkQuestCompletion();const now=Date.now();if(S.activeQuests.length<3&&(!S.questRefreshAt||now>=S.questRefreshAt)){refreshQuests();S.questRefreshAt=now+2*60*1000}let html="";S.activeQuests.forEach((q,idx)=>{const remaining=q.expiresAt?Math.max(0,Math.floor((q.expiresAt-now)/1000)):0;const min=Math.floor(remaining/60),sec=remaining%60;const urgent=remaining<120;const cardClass=q.completed?"completed":(remaining<=0?"failed":"");html+=`<div class="quest-card ${cardClass}"><div class="q-header"><span class="q-name">${q.completed?'✅ ':''}${q.name}</span><span class="q-timer ${urgent?'urgent':'normal'}">⏱ ${min}:${sec.toString().padStart(2,'0')}</span></div><div class="q-desc">${q.desc}</div><div class="q-progress">进度：${q.progress||0}/${q.count||1}${q.type==='survive'?' 分钟':''}</div><div class="q-reward">🎁 ${q.reward.gold}金${q.reward.itemTid?' + '+getEquipName(q.reward.itemTid):''}</div><div class="q-actions">${q.completed?`<button class="primary small" onclick="claimQuestById(${idx})">领取奖励</button>`:`<button class="small danger" onclick="abandonQuest(${idx})">放弃</button>`}</div></div>`});if(S.activeQuests.length===0)html=`<div style="color:var(--muted);text-align:center;padding:20px;">暂无悬赏令<br><span style="font-size:10px;">等待任务板刷新……</span></div>`;el("questList").innerHTML=html;const secToRefresh=S.questRefreshAt?Math.max(0,Math.floor((S.questRefreshAt-now)/1000)):0;el("questRefreshInfo").textContent=`刷新倒计时: ${Math.floor(secToRefresh/60)}:${(secToRefresh%60).toString().padStart(2,'0')}`}

function renderShop(){let html="";SHOP_ITEMS.forEach(item=>{const held=S.expedition.consumables[item.id]||0;const canBuy=!S.expedition.active&&S.gold>=item.price&&held<item.maxCarry;html+=`<div class="shop-card" style="flex:1;min-width:140px;background:var(--panel-2);border:1px solid var(--line);border-radius:3px;padding:12px;text-align:center;"><div style="font-size:22px;">${item.icon}</div><div style="font-size:14px;color:var(--moon);margin:4px 0;">${item.name}</div><div style="font-size:10px;color:var(--muted);margin-bottom:6px;">${item.desc}</div><div style="font-size:10px;color:var(--muted);margin-bottom:6px;">携带: ${held}/${item.maxCarry}</div><button class="small primary" ${!canBuy?'disabled':''} onclick="buyConsumable('${item.id}')">${item.price}金</button></div>`});el("shopItems").innerHTML=html}

function renderSmith(subtab){S._smithTab=subtab;document.querySelectorAll(".smith-tab").forEach(b=>b.classList.remove("active"));const btn=document.querySelector(`.smith-tab[data-smith="${subtab}"]`);if(btn)btn.classList.add("active");document.querySelectorAll(".smith-content").forEach(p=>p.classList.remove("active"));const panel=document.getElementById("smith-"+subtab);if(panel)panel.classList.add("active");el("identifyBadge").textContent=S.inventory.filter(i=>i.unidentified).length>0?`(${S.inventory.filter(i=>i.unidentified).length})`:"";const smithMul=S.hero.race==="dwarf"?0.7:1;let sellHtml="";if(S.inventory.length===0)sellHtml=`<div style="color:var(--muted);text-align:center;padding:20px;">没有可出售的物品</div>`;else S.inventory.forEach((item,i)=>{sellHtml+=`<div class="sell-row"><span class="${'rarity-'+item.rarity}">${item.unidentified?'🔍 ':''}${item.name} ${item.type!=="material"?`[${Math.round(item.durability)}/${item.maxDurability}]`:''}</span><span class="sell-price">${item.sellPrice}金</span><button class="small" style="border-color:var(--candle);color:var(--candle);" onclick="sellItem(${i})">出售</button></div>`});el("smith-sell").innerHTML=sellHtml;let idHtml="";const unidItems=S.inventory.filter(i=>i.unidentified);if(unidItems.length===0)idHtml=`<div style="color:var(--muted);text-align:center;padding:20px;">没有待鉴定的物品<br><span style="font-size:10px;">深渊中偶尔能发现需要鉴定的装备</span></div>`;else unidItems.forEach(item=>{const cost=Math.round((item.sellPrice||10)*0.4*smithMul);idHtml+=`<div class="sell-row"><span>🔍 ${item.name}</span><span class="sell-price">鉴定费 ${cost}金</span><button class="small primary" onclick="identifyItem('${item.id}')">鉴定</button></div>`});el("smith-identify").innerHTML=idHtml;let craftHtml=`<table class="craft-table"><tr><th>名称</th><th>类型</th><th>稀有度</th><th>材料</th><th>金币</th><th></th></tr>`;CRAFT_RECIPES.forEach(recipe=>{const locked=!S.unlockedLayers.includes(recipe.needLayer);const resultTpl=EQUIP_TEMPLATES.find(e=>e.id===recipe.result.tid);const name=resultTpl?resultTpl.name:recipe.name;const rarity=resultTpl?resultTpl.rarity:"common";const type=resultTpl?resultTpl.type:"?";const matsText=recipe.materials.map(m=>`${getMaterialName(m.mid)}×${m.qty}`).join(" + ");const craftCost=Math.round(recipe.cost*smithMul);const canCraft=!locked&&recipe.materials.every(m=>countMaterial(m.mid)>=m.qty)&&S.gold>=craftCost&&S.inventory.length<getBagCapacity();craftHtml+=`<tr class="${locked?'locked-row':''}"><td class="${'rarity-'+rarity}">${name}</td><td>${slotLabel(type)}</td><td>${RARITY[rarity]?RARITY[rarity].name:'?'}</td><td>${matsText}</td><td>${craftCost}金${smithMul<1?' (-30%)':''}</td><td>${locked?`<span style="font-size:10px;color:var(--muted);">需要${LAYERS[recipe.needLayer].name}</span>`:`<button class="small primary" ${!canCraft?'disabled':''} onclick="craftItem('${recipe.id}')">打造</button>`}</td></tr>`});craftHtml+=`</table>`;el("smith-craft").innerHTML=craftHtml}

function renderAbyssGate(){let html="";LAYERS.forEach((layer,i)=>{const unlocked=S.unlockedLayers.includes(i);const selected=S.selectedLayer===i;html+=`<div class="layer-card ${unlocked?'':'locked'} ${selected?'selected':''}" ${unlocked?`onclick="selectLayer(${i})"`:''}><div class="l-name">${unlocked?'🔓':'🔒'} ${layer.name}</div><div class="l-depth">${layer.startDepth} - ${layer.maxDepth>=999?'∞':layer.maxDepth} 尺</div><div class="l-monsters">🐉 ${layer.monsters.slice(0,3).join(' · ')}${layer.monsters.length>3?' …':''}</div><div class="l-danger">危险等级：${layer.danger}</div>${!unlocked?`<div class="l-unlock">${layer.unlockMsg||'?'}</div>`:''}${layer.unlockBonus?`<div class="l-unlock" style="color:var(--candle-dim);">${layer.unlockBonus}</div>`:''}</div>`});el("layerCards").innerHTML=html;const layer=LAYERS[S.selectedLayer];const unlocked=S.unlockedLayers.includes(S.selectedLayer);el("abyssAction").innerHTML=unlocked?`<button class="primary" style="font-size:16px;padding:12px 40px;" onclick="startExpedition(${S.selectedLayer})">⚔️ 从「${layer.name}」出征</button>`:`<span style="color:var(--muted);">该层级尚未解锁</span>`}

function renderChurch(){const now=Date.now();const onCooldown=S.prayerCooldown>now;const remaining=onCooldown?S.prayerCooldown-now:0;const hrs=Math.floor(remaining/3600000);const mins=Math.floor((remaining%3600000)/60000);if(S.activeBlessing){el("churchStatus").innerHTML=`<span style="color:var(--candle);">当前祝福生效中：</span>`;el("churchBuff").innerHTML=`<span style="font-size:18px;">${S.activeBlessing.icon} <strong style="color:var(--candle);">${S.activeBlessing.name}</strong></span><br><span style="font-size:12px;color:var(--muted);">${S.activeBlessing.desc}（下次远征生效）</span>`;el("prayBtn").disabled=true;el("prayBtn").textContent="祝福已就绪，出征吧"}else if(onCooldown){el("churchStatus").innerHTML=`<span style="color:var(--muted);">祷告后需静候神明的回应……</span>`;el("churchBuff").innerHTML=`<span style="font-size:13px;color:var(--muted);">冷却剩余：</span><span style="font-size:16px;color:var(--sanity);">${hrs}时${mins}分</span>`;el("prayBtn").disabled=true;el("prayBtn").textContent=`⏳ ${hrs}时${mins}分后可祈祷`}else{el("churchStatus").innerHTML=`<span style="color:var(--muted);">在深渊礼拜堂中静心祈祷，祈求神明的眷顾。</span>`;el("churchBuff").innerHTML=`<span style="font-size:12px;color:var(--muted);">可能获得的祝福：</span><br><span style="font-size:11px;color:var(--muted);">${BLESSINGS.map(b=>b.icon+b.name).join(' · ')}</span>`;el("prayBtn").disabled=false;el("prayBtn").textContent="🕯️ 祈 祷"}const s=calcHeroStats();const effMax=S.hero.maxSanity+s.maxSanityBonus;const cost=Math.ceil((effMax-S.hero.sanity)*1.5);const canRestore=S.hero.sanity<effMax&&S.gold>=cost;el("churchRestore").innerHTML=`<span style="font-size:12px;color:var(--muted);">恢复神智 · ${S.hero.sanity>=effMax?'神智已满':cost+' 金'}</span>`;const rstBtn=document.getElementById("restoreSanityBtn");if(rstBtn){rstBtn.disabled=!canRestore;rstBtn.textContent=S.hero.sanity>=effMax?"🙏 神智已满":`🙏 静心祈祷 · ${cost}金`}}
function doPray(){if(S.prayerCooldown>Date.now()||S.activeBlessing)return;const b=BLESSINGS[Math.floor(Math.random()*BLESSINGS.length)];S.activeBlessing={type:b.id,name:b.name,desc:b.desc,icon:b.icon,apply:b.apply};S.prayerCooldown=Date.now()+3*60*60*1000;pushLog(`⛪ 你在礼拜堂中虔诚祈祷，获得了「${b.name}」——${b.desc}`,"good");render();save()}
function restoreSanity(){const s=calcHeroStats();const effMax=S.hero.maxSanity+s.maxSanityBonus;const cost=Math.ceil((effMax-S.hero.sanity)*1.5);if(S.hero.sanity>=effMax||S.gold<cost)return;S.gold-=cost;S.hero.sanity=effMax;pushLog("你在残烛前静坐良久，心神渐渐安定。","good");render();save()}

function warehouseUpgradeCost(){const level=(S.warehouseSlots-20)/5;return Math.round(100*Math.pow(1.5,level))}
function upgradeWarehouse(){if(S.warehouseSlots>=50)return;const cost=warehouseUpgradeCost();if(S.gold<cost)return;S.gold-=cost;S.warehouseSlots+=5;pushLog(`📦 秘库扩容至 ${S.warehouseSlots} 格，花费 ${cost} 金。`,"good");render();save()}
function depositItem(idx){const item=S.inventory[idx];if(!item||item.unidentified||S.warehouse.length>=S.warehouseSlots)return;if(item.type==="material"&&item.templateId){const existing=S.warehouse.find(w=>w.templateId===item.templateId);if(existing&&existing.qty!==undefined){existing.qty+=1;S.inventory.splice(idx,1);render();save();return}S.warehouse.push({...item,qty:1})}else S.warehouse.push(item);S.inventory.splice(idx,1);render();save()}
function withdrawItem(whIdx){const item=S.warehouse[whIdx];if(!item||S.inventory.length>=getBagCapacity())return;if(item.qty!==undefined&&item.qty>1){const single={...item};delete single.qty;S.inventory.push(single);item.qty-=1;if(item.qty<=0)S.warehouse.splice(whIdx,1)}else{S.inventory.push(item);S.warehouse.splice(whIdx,1)}render();save()}
function renderWarehouse(){const wh=S.warehouse,inv=S.inventory;el("whCount").textContent=wh.length+"/"+S.warehouseSlots;if(S.warehouseSlots>=50)el("whUpgradeRow").innerHTML=`<span style="font-size:11px;color:var(--candle-dim);">秘库已满级 (50格)</span>`;else{const cost=warehouseUpgradeCost();el("whUpgradeRow").innerHTML=`<button class="small" ${S.gold<cost?'disabled':''} onclick="upgradeWarehouse()">扩容 +5格 · ${cost}金</button>`}if(wh.length===0)el("whPanel").innerHTML=`<div style="color:var(--muted);font-size:11px;text-align:center;padding:16px;">仓库空空如也</div>`;else el("whPanel").innerHTML=wh.map((item,i)=>{const name=item.name+(item.qty>1?` ×${item.qty}`:"");const sub=item.type!=="material"?`<span class="inv-dur">${Math.round(item.durability)}/${item.maxDurability}</span>`:"";return `<div class="inv-row"><span class="inv-name ${'rarity-'+item.rarity}">${name}</span>${sub}<span class="inv-act"><button class="small" onclick="withdrawItem(${i})">取出</button></span></div>`}).join("");if(inv.length===0)el("whInvPanel").innerHTML=`<div style="color:var(--muted);font-size:11px;text-align:center;padding:12px;">背包空空如也</div>`;else el("whInvPanel").innerHTML=inv.map((item,i)=>{const canDeposit=!item.unidentified&&wh.length<S.warehouseSlots;return `<div class="inv-row"><span class="inv-name ${'rarity-'+item.rarity}">${item.unidentified?'🔍 ':''}${item.name}</span><span class="inv-dur">${item.type!=="material"?Math.round(item.durability)+'/'+item.maxDurability:''}</span><span class="inv-act"><button class="small" ${!canDeposit?'disabled':''} onclick="depositItem(${i})">${item.unidentified?'🔍鉴定后':'存入'}</button></span></div>`}).join("")}

function confirmDeleteSave(){showModal("确认删除存档","此操作将永久删除你的所有进度，包括金币、装备、怪物志和最深记录。此操作不可撤销。",[{label:"取消",cls:"",action:"hideModal()"},{label:"确认删除",cls:"danger",action:"deleteSave()"}])}
function deleteSave(){S._deleting=true;localStorage.removeItem(SAVE_KEY);hideModal();location.reload()}
function renderSettings(){const el2=document.getElementById("settingsStats");if(el2)el2.innerHTML=`最深记录：<span style="color:var(--candle);">${S.maxDepthRecord.toFixed(1)}</span> 尺<br>持有金币：<span style="color:var(--candle);">${S.gold}</span><br>怪物志：<span style="color:var(--candle);">${Object.keys(S.bestiary).length}</span> 种<br>遗物收集：<span style="color:var(--candle);">${Object.keys(S.relicsOwned).length}</span> / ${RELICS.length}<br>最深层级：<span style="color:var(--candle);">${S.unlockedLayers.length>0?LAYERS[Math.max(...S.unlockedLayers)].name:'浅层回廊'}</span><br>当前种族：<span style="color:var(--candle);">${({human:'👤 人类',elf:'🧝 精灵',bear:'🐻 熊人',dwarf:'⛏️ 矮人'})[S.hero.race]||'???'}</span>`}

function renderTavern(){el("tavernRecord").textContent=S.maxDepthRecord.toFixed(1)}

function renderExpedition(){const ex=S.expedition,stats=calcHeroStats(),h=S.hero;const raceNames={human:"👤 人类",elf:"🧝 精灵",bear:"🐻 熊人",dwarf:"⛏️ 矮人"};el("expRace").textContent=raceNames[h.race]||"👤 人类";el("expLayerName").textContent=LAYERS[ex.layerIndex]?LAYERS[ex.layerIndex].name:"???";el("expCarriedGold").textContent=ex.carriedGold||0;el("hpNum").textContent=`${Math.max(0,Math.round(h.hp))} / ${stats.maxHp}`;el("hpFill").style.width=Math.max(0,(h.hp/stats.maxHp*100))+"%";el("atkNum").textContent=stats.atk;el("defNum").textContent=stats.def;el("dodgeNum").textContent=Math.round(stats.dodge*100)+"%";el("sanityNum").textContent=Math.round(h.sanity)+"/"+(h.maxSanity+stats.maxSanityBonus);el("sanityFill").style.width=(h.sanity/(h.maxSanity+stats.maxSanityBonus)*100)+"%";el("goldNumH").textContent=S.gold;el("depthNum").textContent=ex.depth.toFixed(1);el("recordNum").textContent=S.maxDepthRecord.toFixed(1);const torchPct=ex.active?Math.max(0,ex.torch/ex.maxTorch*100):100;el("torchFill").style.height=torchPct+"%";el("torchPct").textContent=Math.round(torchPct);const flame=el("flame");flame.style.animationDuration=ex.active?(0.6+torchPct/100*1.2)+"s":"1.6s";flame.style.opacity=ex.active?(0.4+torchPct/100*0.6):1;el("expLayerLabel").textContent=LAYERS[ex.layerIndex]?LAYERS[ex.layerIndex].name:"???";el("expDepthMax").textContent=LAYERS[ex.layerIndex]?LAYERS[ex.layerIndex].maxDepth+"尺":"?";if(ex.itemsFound.length===0)el("expItemsBag").innerHTML=`<div style="color:var(--muted);font-size:10px;text-align:center;">暂无战利品</div>`;else el("expItemsBag").innerHTML=ex.itemsFound.map(item=>`<div class="row"><span class="${'rarity-'+item.rarity}">${item.name}</span></div>`).join("");const box=el("encounterBox");if(!ex.active){box.className="encounter empty";box.innerHTML="远征结束"}else if(!ex.monster){if(ex.event&&ex.event.type!=="narrative"){const ev=ex.event;box.className="encounter";box.innerHTML=`<div style="font-size:15px;color:var(--candle);margin-bottom:8px;">${ev.name||"……"}</div><div style="font-size:12px;color:var(--muted);margin-bottom:12px;">${ev.type==="curio"?"一件奇物出现在你面前。":ev.type==="trap"?"前方有危险的气息。":"一处可以歇脚的地方。"}</div><div style="display:flex;gap:8px;"><button class="small" onclick="resolveEvent('safe')" style="flex:1;">${ev.safe.text||"稳妥行事"}</button><button class="small danger" onclick="resolveEvent('risky')" style="flex:1;">${ev.risky.text||"冒险一试"}</button></div>`}else{box.className="encounter empty";box.innerHTML="回廊寂静无声…"}}else{box.className="encounter";const pct=Math.max(0,ex.monster.hp/ex.monster.maxHp*100);box.innerHTML=`<div class="monster-name">${ex.monster.name}</div><div class="monster-hp-wrap"><div class="monster-hp"><div style="width:${pct}%"></div></div><div class="monster-hp-num">${Math.max(0,Math.round(ex.monster.hp))}/${ex.monster.maxHp}</div></div>`}el("descendBtn").disabled=ex.active;el("retreatBtn").disabled=!ex.active;el("logBox").innerHTML=S.logs.map(l=>`<div class="entry ${l.cls}">${l.text}</div>`).join("");const skillBar=document.getElementById("skillBar");if(skillBar){const bloodrageBlock=h.race==="bear"&&h.sanity<h.maxSanity*0.3;const allSkills=[...SKILLS.filter(s=>!s.race||s.race===h.race)];skillBar.innerHTML=allSkills.map(sk=>{const onCd=ex.skillCooldowns[sk.id]&&ex.skillCooldowns[sk.id]>0;const cdText=onCd?` (${ex.skillCooldowns[sk.id]}s)`:"";let disabled=!ex.active||!ex.monster||bloodrageBlock;if(ex.active&&ex.monster&&!onCd&&!bloodrageBlock){if(sk.costType==="sanity"&&h.sanity<sk.cost)disabled=true;if(sk.costType==="torch"&&ex.torch<sk.cost)disabled=true;if(sk.costType==="hp"&&h.hp<=sk.cost)disabled=true}let cls="skill-btn";if(onCd)cls+=" on-cooldown";const hasBuff=ex.activeBuffs[sk.buffKey];if(hasBuff)cls+=" active-buff";if(sk.id==="allin")cls+=" danger";const text=onCd?sk.name+cdText:sk.name;return `<button class="${cls}" ${disabled?'disabled':''} onclick="useSkill('${sk.id}')">${sk.name}</button>`}).join("")}const consumableBar=document.getElementById("consumableBar");if(consumableBar){const inCombat=ex.active&&ex.monster;consumableBar.innerHTML=SHOP_ITEMS.map(item=>{const held=ex.consumables[item.id]||0;const combatOnly=(item.effect==="holyWater"||item.effect==="firebomb");const canUse=ex.active&&held>0&&(!combatOnly||inCombat);return `<button class="skill-btn" ${!canUse?'disabled':''} onclick="useConsumable('${item.id}')" title="${item.desc} (剩余 ${held})">${item.icon} ${held}</button>`}).join("")}document.getElementById("headerEyebrow").textContent="深 渊 · 探 索 · 生 存";document.getElementById("headerSub").textContent="火光摇曳，深渊在等待"}

function equipFromInv(idx){const item=S.inventory[idx];if(!item||item.unidentified||item.type==="material")return;const slotKey=item.type;if(!S.equipment.hasOwnProperty(slotKey))return;const unlockMap={weapon:1,body:1,hands:2,feet:3,head:5,waist:6,cloak:7,relic:8};if(S.equipSlots<(unlockMap[slotKey]||1))return;const old=S.equipment[slotKey];S.equipment[slotKey]=item;if(old){if(S.inventory.length>=getBagCapacity()){S.gold+=Math.floor(old.sellPrice||1);pushLog(`背包已满，换下的${old.name}自动出售。`,"dim")}else{S.inventory.splice(idx,1,old);pushLog(`将${old.name}换为${item.name}。`,"dim")}}else{S.inventory.splice(idx,1);pushLog(`装备了${item.name}。`,"dim")}render();save()}
function unequipItem(slotKey){const item=S.equipment[slotKey];if(!item)return;if(S.inventory.length>=getBagCapacity()){S.gold+=Math.floor(item.sellPrice||1);S.equipment[slotKey]=null;pushLog(`背包已满，卸下${item.name}后自动出售，获得 ${Math.floor(item.sellPrice||1)} 金。`,"dim")}else{S.inventory.push(item);S.equipment[slotKey]=null;pushLog(`卸下了${item.name}。`,"dim")}render();save()}
function repairEquipment(slotKey){const item=S.equipment[slotKey];const cost=repairCost(item);if(cost<=0||S.gold<cost)return;S.gold-=cost;item.durability=item.maxDurability;pushLog(`修复了${item.name}，花费 ${cost} 金。`,"dim");render();save()}
function sellItem(idx){const item=S.inventory[idx];if(!item)return;S.gold+=item.sellPrice||1;pushLog(`出售了${item.name}，获得 ${item.sellPrice||1} 金。`,"dim");S.inventory.splice(idx,1);render();save()}
function discardItem(idx){S.inventory.splice(idx,1);pushLog("丢弃了一件物品。","dim");render();save()}
function identifyItem(itemId){const item=S.inventory.find(i=>i.id===itemId);if(!item||!item.unidentified)return;const smithMul=S.hero.race==="dwarf"?0.7:1;const cost=Math.round((item.sellPrice||10)*0.4*smithMul);if(S.gold<cost){pushLog("金币不足，无法鉴定。","warn");render();save();return}S.gold-=cost;item.unidentified=false;if(item.templateId){const tpl=EQUIP_TEMPLATES.find(e=>e.id===item.templateId);if(tpl)item.name=tpl.name}pushLog(`鉴定完成——是「${item.name}」！`,"good");render();save()}
function claimQuest(q){if(!q.completed)return;S.gold+=q.reward.gold;pushLog(`完成任务「${q.name}」，获得 ${q.reward.gold} 金。`,"good");if(q.reward.itemTid){const tpl=EQUIP_TEMPLATES.find(e=>e.id===q.reward.itemTid);if(tpl&&S.inventory.length<getBagCapacity()){const item={id:tpl.id+"_quest_"+Date.now()+"_"+Math.random().toString(36).slice(2,6),templateId:tpl.id,name:tpl.name,type:tpl.type,rarity:tpl.rarity,stats:{...tpl.baseStats},durability:tpl.baseDura,maxDurability:tpl.baseDura,sellPrice:tpl.baseVal,unidentified:false};S.inventory.push(item);pushLog(`获得了 ${tpl.name}！`,"good")}}S.completedQuestIds.push(q.poolId);S.activeQuests=S.activeQuests.filter(aq=>aq!==q);S.questRefreshAt=Date.now()+2*60*1000}
function refreshQuests(){if(S.activeQuests.length>=3)return;const need=3-S.activeQuests.length;for(let i=0;i<need;i++){const q=generateQuest();if(q)S.activeQuests.push(q)}}

function switchToCamp(){document.body.classList.remove("in-expedition");renderCampTab(S._campTab||"prep")}
function switchToExpedition(){document.body.classList.add("in-expedition")}

function repairCost(item){if(!item||item.durability>=item.maxDurability)return 0;const rarityData=RARITY[item.rarity]||RARITY.common;const missing=item.maxDurability-item.durability;return Math.max(1,Math.round(missing*0.02*(item.sellPrice||5)*rarityData.craftCostMul))}

function render(){if(document.body.classList.contains("in-expedition"))renderExpedition();else renderCamp()}
function renderCamp(){el("goldNumH").textContent=S.gold;const tab=S._campTab||"prep";renderPrep();renderQuestBoard();renderShop();renderSmith(tab==="smith"?S._smithTab||"sell":"sell");renderAbyssGate();renderChurch();renderWarehouse();renderSettings();renderTavern();document.getElementById("headerEyebrow").textContent="营 地 · 整 备 · 出 征";document.getElementById("headerSub").textContent="火尽人归，深处不留光"}
function renderCampTab(tab){S._campTab=tab;document.querySelectorAll(".nav-tab").forEach(b=>b.classList.remove("active"));const btn=document.querySelector(`.nav-tab[data-tab="${tab}"]`);if(btn)btn.classList.add("active");document.querySelectorAll("#camp-view .tab-content").forEach(p=>p.classList.remove("active"));const panel=document.getElementById("tab-"+tab);if(panel)panel.classList.add("active");renderCamp()}

function renderPrep(){const eq=S.equipment,maxSlots=S.equipSlots;const allSlots={weapon:{label:"🗡 武器",side:"attack",desc:"攻击力·暴击",unlockAt:1},hands:{label:"✋ 手部",side:"attack",desc:"暴击率·攻速",unlockAt:2},relic:{label:"🔮 圣物",side:"attack",desc:"被动·复活",unlockAt:8},cloak:{label:"🧥 披风",side:"attack",desc:"火把·黑暗",unlockAt:7},head:{label:"🎩 头部",side:"defense",desc:"神智抗性",unlockAt:5},body:{label:"🛡 躯干",side:"defense",desc:"防御力·生命",unlockAt:1},waist:{label:"🎽 腰部",side:"defense",desc:"背包扩容",unlockAt:6},feet:{label:"👢 足部",side:"defense",desc:"闪避·移动",unlockAt:3}};const stats=calcHeroStats();const totalBag=S.bagCapacity+stats.bagSlots;const raceNames={human:"👤 人类",elf:"🧝 精灵",bear:"🐻 熊人",dwarf:"⛏️ 矮人"};function slotHTML(key){const cfg=allSlots[key];const locked=maxSlots<cfg.unlockAt;const lockHints={5:"到达中层甬道解锁",6:"到达中层甬道解锁",7:"到达深层墓室解锁",8:"到达绝渊回廊解锁"};const item=eq[key];if(locked)return `<div class="equip-slot" style="opacity:0.4"><span class="slot-label">${cfg.label}</span><span class="slot-empty">🔒 ${lockHints[cfg.unlockAt]||"未解锁"}</span></div>`;if(item){const durPct=item.maxDurability>0?Math.round(item.durability/item.maxDurability*100):100;const warnClass=durPct<25?"durability-warn":"";return `<div class="equip-slot ${warnClass}"><div><span class="slot-label">${cfg.label}</span><span style="font-size:9px;color:var(--muted);"> ${cfg.desc}</span><br><span class="slot-item ${'rarity-'+item.rarity}">${item.name}</span><span style="font-size:10px;color:${durPct<25?'var(--blood-bright)':'var(--muted)'};"> 耐久 ${Math.round(item.durability)}/${item.maxDurability}</span></div><div class="slot-actions">${item.durability<item.maxDurability?`<button class="small" onclick="repairEquipment('${key}');event.stopPropagation();">修 ${repairCost(item)}金</button>`:""}<button class="small danger" onclick="unequipItem('${key}');event.stopPropagation();">卸</button></div></div>`}return `<div class="equip-slot"><span class="slot-label">${cfg.label}</span><span style="font-size:9px;color:var(--muted);"> ${cfg.desc}</span><span class="slot-empty">空</span></div>`}const attackSlots=["weapon","hands","relic","cloak"];const defenseSlots=["head","body","waist","feet"];el("equipSlots").innerHTML=`<div style="font-size:12px;color:var(--candle-dim);margin-bottom:8px;">种族：${raceNames[S.hero.race]||"👤 人类"}</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;"><div><div style="text-align:center;font-size:11px;color:var(--candle-dim);letter-spacing:0.15em;margin-bottom:6px;border-bottom:1px solid var(--line);padding-bottom:4px;">— 攻 势 —</div>${attackSlots.map(k=>slotHTML(k)).join("")}</div><div><div style="text-align:center;font-size:11px;color:var(--candle-dim);letter-spacing:0.15em;margin-bottom:6px;border-bottom:1px solid var(--line);padding-bottom:4px;">— 守 御 —</div>${defenseSlots.map(k=>slotHTML(k)).join("")}</div></div>`;const inv=S.inventory;el("invCount").textContent=inv.length+"/"+totalBag;if(inv.length===0)el("invPanel").innerHTML=`<div style="color:var(--muted);font-size:12px;text-align:center;padding:20px;">背包空空如也<br><span style="font-size:10px;">深入深渊，获取战利品</span></div>`;else el("invPanel").innerHTML=inv.map((item,i)=>{const canEquip=!item.unidentified&&item.type!=="material"&&maxSlots>=(allSlots[item.type]?allSlots[item.type].unlockAt:99);const durText=item.type!=="material"?`<span class="inv-dur">${Math.round(item.durability)}/${item.maxDurability}</span>`:"";return `<div class="inv-row"><span class="inv-name ${'rarity-'+item.rarity}">${item.unidentified?'🔍 ':''}${item.name}</span>${durText}<span class="inv-act">${canEquip?`<button class="small" onclick="equipFromInv(${i})">装备</button>`:""}<button class="small" style="border-color:var(--candle);color:var(--candle);" onclick="sellItem(${i})">出售 ${item.sellPrice}金</button><button class="small danger" onclick="discardItem(${i})">丢弃</button></span></div>`}).join("")}

function renderQuestBoard(){checkQuestCompletion();const now=Date.now();if(S.activeQuests.length<3&&(!S.questRefreshAt||now>=S.questRefreshAt)){refreshQuests();S.questRefreshAt=now+2*60*1000}let html="";S.activeQuests.forEach((q,idx)=>{const remaining=q.expiresAt?Math.max(0,Math.floor((q.expiresAt-now)/1000)):0;const min=Math.floor(remaining/60),sec=remaining%60;const urgent=remaining<120;const cardClass=q.completed?"completed":(remaining<=0?"failed":"");html+=`<div class="quest-card ${cardClass}"><div class="q-header"><span class="q-name">${q.completed?'✅ ':''}${q.name}</span><span class="q-timer ${urgent?'urgent':'normal'}">⏱ ${min}:${sec.toString().padStart(2,'0')}</span></div><div class="q-desc">${q.desc}</div><div class="q-progress">进度：${q.progress||0}/${q.count||1}${q.type==='survive'?' 分钟':''}</div><div class="q-reward">🎁 ${q.reward.gold}金${q.reward.itemTid?' + '+getEquipName(q.reward.itemTid):''}</div><div class="q-actions">${q.completed?`<button class="primary small" onclick="claimQuestById(${idx})">领取奖励</button>`:`<button class="small danger" onclick="abandonQuest(${idx})">放弃</button>`}</div></div>`});if(S.activeQuests.length===0)html=`<div style="color:var(--muted);text-align:center;padding:20px;">暂无悬赏令<br><span style="font-size:10px;">等待任务板刷新……</span></div>`;el("questList").innerHTML=html;const secToRefresh=S.questRefreshAt?Math.max(0,Math.floor((S.questRefreshAt-now)/1000)):0;el("questRefreshInfo").textContent=`刷新倒计时: ${Math.floor(secToRefresh/60)}:${(secToRefresh%60).toString().padStart(2,'0')}`}

function renderShop(){let html="";SHOP_ITEMS.forEach(item=>{const held=S.expedition.consumables[item.id]||0;const canBuy=!S.expedition.active&&S.gold>=item.price&&held<item.maxCarry;html+=`<div class="shop-card" style="flex:1;min-width:140px;background:var(--panel-2);border:1px solid var(--line);border-radius:3px;padding:12px;text-align:center;"><div style="font-size:22px;">${item.icon}</div><div style="font-size:14px;color:var(--moon);margin:4px 0;">${item.name}</div><div style="font-size:10px;color:var(--muted);margin-bottom:6px;">${item.desc}</div><div style="font-size:10px;color:var(--muted);margin-bottom:6px;">携带: ${held}/${item.maxCarry}</div><button class="small primary" ${!canBuy?'disabled':''} onclick="buyConsumable('${item.id}')">${item.price}金</button></div>`});el("shopItems").innerHTML=html}

function renderSmith(subtab){S._smithTab=subtab;document.querySelectorAll(".smith-tab").forEach(b=>b.classList.remove("active"));const btn=document.querySelector(`.smith-tab[data-smith="${subtab}"]`);if(btn)btn.classList.add("active");document.querySelectorAll(".smith-content").forEach(p=>p.classList.remove("active"));const panel=document.getElementById("smith-"+subtab);if(panel)panel.classList.add("active");el("identifyBadge").textContent=S.inventory.filter(i=>i.unidentified).length>0?`(${S.inventory.filter(i=>i.unidentified).length})`:"";const smithMul=S.hero.race==="dwarf"?0.7:1;let sellHtml="";if(S.inventory.length===0)sellHtml=`<div style="color:var(--muted);text-align:center;padding:20px;">没有可出售的物品</div>`;else S.inventory.forEach((item,i)=>{sellHtml+=`<div class="sell-row"><span class="${'rarity-'+item.rarity}">${item.unidentified?'🔍 ':''}${item.name} ${item.type!=="material"?`[${Math.round(item.durability)}/${item.maxDurability}]`:''}</span><span class="sell-price">${item.sellPrice}金</span><button class="small" style="border-color:var(--candle);color:var(--candle);" onclick="sellItem(${i})">出售</button></div>`});el("smith-sell").innerHTML=sellHtml;let idHtml="";const unidItems=S.inventory.filter(i=>i.unidentified);if(unidItems.length===0)idHtml=`<div style="color:var(--muted);text-align:center;padding:20px;">没有待鉴定的物品<br><span style="font-size:10px;">深渊中偶尔能发现需要鉴定的装备</span></div>`;else unidItems.forEach(item=>{const cost=Math.round((item.sellPrice||10)*0.4*smithMul);idHtml+=`<div class="sell-row"><span>🔍 ${item.name}</span><span class="sell-price">鉴定费 ${cost}金</span><button class="small primary" onclick="identifyItem('${item.id}')">鉴定</button></div>`});el("smith-identify").innerHTML=idHtml;let craftHtml=`<table class="craft-table"><tr><th>名称</th><th>类型</th><th>稀有度</th><th>材料</th><th>金币</th><th></th></tr>`;CRAFT_RECIPES.forEach(recipe=>{const locked=!S.unlockedLayers.includes(recipe.needLayer);const resultTpl=EQUIP_TEMPLATES.find(e=>e.id===recipe.result.tid);const name=resultTpl?resultTpl.name:recipe.name;const rarity=resultTpl?resultTpl.rarity:"common";const type=resultTpl?resultTpl.type:"?";const matsText=recipe.materials.map(m=>`${getMaterialName(m.mid)}×${m.qty}`).join(" + ");const craftCost=Math.round(recipe.cost*smithMul);const canCraft=!locked&&recipe.materials.every(m=>countMaterial(m.mid)>=m.qty)&&S.gold>=craftCost&&S.inventory.length<getBagCapacity();craftHtml+=`<tr class="${locked?'locked-row':''}"><td class="${'rarity-'+rarity}">${name}</td><td>${slotLabel(type)}</td><td>${RARITY[rarity]?RARITY[rarity].name:'?'}</td><td>${matsText}</td><td>${craftCost}金${smithMul<1?' (-30%)':''}</td><td>${locked?`<span style="font-size:10px;color:var(--muted);">需要${LAYERS[recipe.needLayer].name}</span>`:`<button class="small primary" ${!canCraft?'disabled':''} onclick="craftItem('${recipe.id}')">打造</button>`}</td></tr>`});craftHtml+=`</table>`;el("smith-craft").innerHTML=craftHtml}

function renderAbyssGate(){let html="";LAYERS.forEach((layer,i)=>{const unlocked=S.unlockedLayers.includes(i);const selected=S.selectedLayer===i;html+=`<div class="layer-card ${unlocked?'':'locked'} ${selected?'selected':''}" ${unlocked?`onclick="selectLayer(${i})"`:''}><div class="l-name">${unlocked?'🔓':'🔒'} ${layer.name}</div><div class="l-depth">${layer.startDepth} - ${layer.maxDepth>=999?'∞':layer.maxDepth} 尺</div><div class="l-monsters">🐉 ${layer.monsters.slice(0,3).join(' · ')}${layer.monsters.length>3?' …':''}</div><div class="l-danger">危险等级：${layer.danger}</div>${!unlocked?`<div class="l-unlock">${layer.unlockMsg||'?'}</div>`:''}${layer.unlockBonus?`<div class="l-unlock" style="color:var(--candle-dim);">${layer.unlockBonus}</div>`:''}</div>`});el("layerCards").innerHTML=html;const layer=LAYERS[S.selectedLayer];const unlocked=S.unlockedLayers.includes(S.selectedLayer);el("abyssAction").innerHTML=unlocked?`<button class="primary" style="font-size:16px;padding:12px 40px;" onclick="startExpedition(${S.selectedLayer})">⚔️ 从「${layer.name}」出征</button>`:`<span style="color:var(--muted);">该层级尚未解锁</span>`}

function renderChurch(){const now=Date.now();const onCooldown=S.prayerCooldown>now;const remaining=onCooldown?S.prayerCooldown-now:0;const hrs=Math.floor(remaining/3600000);const mins=Math.floor((remaining%3600000)/60000);if(S.activeBlessing){el("churchStatus").innerHTML=`<span style="color:var(--candle);">当前祝福生效中：</span>`;el("churchBuff").innerHTML=`<span style="font-size:18px;">${S.activeBlessing.icon} <strong style="color:var(--candle);">${S.activeBlessing.name}</strong></span><br><span style="font-size:12px;color:var(--muted);">${S.activeBlessing.desc}（下次远征生效）</span>`;el("prayBtn").disabled=true;el("prayBtn").textContent="祝福已就绪，出征吧"}else if(onCooldown){el("churchStatus").innerHTML=`<span style="color:var(--muted);">祷告后需静候神明的回应……</span>`;el("churchBuff").innerHTML=`<span style="font-size:13px;color:var(--muted);">冷却剩余：</span><span style="font-size:16px;color:var(--sanity);">${hrs}时${mins}分</span>`;el("prayBtn").disabled=true;el("prayBtn").textContent=`⏳ ${hrs}时${mins}分后可祈祷`}else{el("churchStatus").innerHTML=`<span style="color:var(--muted);">在深渊礼拜堂中静心祈祷，祈求神明的眷顾。</span>`;el("churchBuff").innerHTML=`<span style="font-size:12px;color:var(--muted);">可能获得的祝福：</span><br><span style="font-size:11px;color:var(--muted);">${BLESSINGS.map(b=>b.icon+b.name).join(' · ')}</span>`;el("prayBtn").disabled=false;el("prayBtn").textContent="🕯️ 祈 祷"}const s=calcHeroStats();const effMax=S.hero.maxSanity+s.maxSanityBonus;const cost=Math.ceil((effMax-S.hero.sanity)*1.5);const canRestore=S.hero.sanity<effMax&&S.gold>=cost;el("churchRestore").innerHTML=`<span style="font-size:12px;color:var(--muted);">恢复神智 · ${S.hero.sanity>=effMax?'神智已满':cost+' 金'}</span>`;const rstBtn=document.getElementById("restoreSanityBtn");if(rstBtn){rstBtn.disabled=!canRestore;rstBtn.textContent=S.hero.sanity>=effMax?"🙏 神智已满":`🙏 静心祈祷 · ${cost}金`}}
function doPray(){if(S.prayerCooldown>Date.now()||S.activeBlessing)return;const b=BLESSINGS[Math.floor(Math.random()*BLESSINGS.length)];S.activeBlessing={type:b.id,name:b.name,desc:b.desc,icon:b.icon,apply:b.apply};S.prayerCooldown=Date.now()+3*60*60*1000;pushLog(`⛪ 你在礼拜堂中虔诚祈祷，获得了「${b.name}」——${b.desc}`,"good");render();save()}
function restoreSanity(){const s=calcHeroStats();const effMax=S.hero.maxSanity+s.maxSanityBonus;const cost=Math.ceil((effMax-S.hero.sanity)*1.5);if(S.hero.sanity>=effMax||S.gold<cost)return;S.gold-=cost;S.hero.sanity=effMax;pushLog("你在残烛前静坐良久，心神渐渐安定。","good");render();save()}

function warehouseUpgradeCost(){const level=(S.warehouseSlots-20)/5;return Math.round(100*Math.pow(1.5,level))}
function upgradeWarehouse(){if(S.warehouseSlots>=50)return;const cost=warehouseUpgradeCost();if(S.gold<cost)return;S.gold-=cost;S.warehouseSlots+=5;pushLog(`📦 秘库扩容至 ${S.warehouseSlots} 格，花费 ${cost} 金。`,"good");render();save()}
function depositItem(idx){const item=S.inventory[idx];if(!item||item.unidentified||S.warehouse.length>=S.warehouseSlots)return;if(item.type==="material"&&item.templateId){const existing=S.warehouse.find(w=>w.templateId===item.templateId);if(existing&&existing.qty!==undefined){existing.qty+=1;S.inventory.splice(idx,1);render();save();return}S.warehouse.push({...item,qty:1})}else S.warehouse.push(item);S.inventory.splice(idx,1);render();save()}
function withdrawItem(whIdx){const item=S.warehouse[whIdx];if(!item||S.inventory.length>=getBagCapacity())return;if(item.qty!==undefined&&item.qty>1){const single={...item};delete single.qty;S.inventory.push(single);item.qty-=1;if(item.qty<=0)S.warehouse.splice(whIdx,1)}else{S.inventory.push(item);S.warehouse.splice(whIdx,1)}render();save()}
function renderWarehouse(){const wh=S.warehouse,inv=S.inventory;el("whCount").textContent=wh.length+"/"+S.warehouseSlots;if(S.warehouseSlots>=50)el("whUpgradeRow").innerHTML=`<span style="font-size:11px;color:var(--candle-dim);">秘库已满级 (50格)</span>`;else{const cost=warehouseUpgradeCost();el("whUpgradeRow").innerHTML=`<button class="small" ${S.gold<cost?'disabled':''} onclick="upgradeWarehouse()">扩容 +5格 · ${cost}金</button>`}if(wh.length===0)el("whPanel").innerHTML=`<div style="color:var(--muted);font-size:11px;text-align:center;padding:16px;">仓库空空如也</div>`;else el("whPanel").innerHTML=wh.map((item,i)=>{const name=item.name+(item.qty>1?` ×${item.qty}`:"");const sub=item.type!=="material"?`<span class="inv-dur">${Math.round(item.durability)}/${item.maxDurability}</span>`:"";return `<div class="inv-row"><span class="inv-name ${'rarity-'+item.rarity}">${name}</span>${sub}<span class="inv-act"><button class="small" onclick="withdrawItem(${i})">取出</button></span></div>`}).join("");if(inv.length===0)el("whInvPanel").innerHTML=`<div style="color:var(--muted);font-size:11px;text-align:center;padding:12px;">背包空空如也</div>`;else el("whInvPanel").innerHTML=inv.map((item,i)=>{const canDeposit=!item.unidentified&&wh.length<S.warehouseSlots;return `<div class="inv-row"><span class="inv-name ${'rarity-'+item.rarity}">${item.unidentified?'🔍 ':''}${item.name}</span><span class="inv-dur">${item.type!=="material"?Math.round(item.durability)+'/'+item.maxDurability:''}</span><span class="inv-act"><button class="small" ${!canDeposit?'disabled':''} onclick="depositItem(${i})">${item.unidentified?'🔍鉴定后':'存入'}</button></span></div>`}).join("")}

function confirmDeleteSave(){showModal("确认删除存档","此操作将永久删除你的所有进度，包括金币、装备、怪物志和最深记录。此操作不可撤销。",[{label:"取消",cls:"",action:"hideModal()"},{label:"确认删除",cls:"danger",action:"deleteSave()"}])}
function deleteSave(){S._deleting=true;localStorage.removeItem(SAVE_KEY);hideModal();location.reload()}
function renderSettings(){const el2=document.getElementById("settingsStats");if(el2)el2.innerHTML=`最深记录：<span style="color:var(--candle);">${S.maxDepthRecord.toFixed(1)}</span> 尺<br>持有金币：<span style="color:var(--candle);">${S.gold}</span><br>怪物志：<span style="color:var(--candle);">${Object.keys(S.bestiary).length}</span> 种<br>遗物收集：<span style="color:var(--candle);">${Object.keys(S.relicsOwned).length}</span> / ${RELICS.length}<br>最深层级：<span style="color:var(--candle);">${S.unlockedLayers.length>0?LAYERS[Math.max(...S.unlockedLayers)].name:'浅层回廊'}</span><br>当前种族：<span style="color:var(--candle);">${({human:'👤 人类',elf:'🧝 精灵',bear:'🐻 熊人',dwarf:'⛏️ 矮人'})[S.hero.race]||'???'}</span>`}

function renderTavern(){el("tavernRecord").textContent=S.maxDepthRecord.toFixed(1)}

function renderExpedition(){const ex=S.expedition,stats=calcHeroStats(),h=S.hero;const raceNames={human:"👤 人类",elf:"🧝 精灵",bear:"🐻 熊人",dwarf:"⛏️ 矮人"};el("expRace").textContent=raceNames[h.race]||"👤 人类";el("expLayerName").textContent=LAYERS[ex.layerIndex]?LAYERS[ex.layerIndex].name:"???";el("expCarriedGold").textContent=ex.carriedGold||0;el("hpNum").textContent=`${Math.max(0,Math.round(h.hp))} / ${stats.maxHp}`;el("hpFill").style.width=Math.max(0,(h.hp/stats.maxHp*100))+"%";el("atkNum").textContent=stats.atk;el("defNum").textContent=stats.def;el("dodgeNum").textContent=Math.round(stats.dodge*100)+"%";el("sanityNum").textContent=Math.round(h.sanity)+"/"+(h.maxSanity+stats.maxSanityBonus);el("sanityFill").style.width=(h.sanity/(h.maxSanity+stats.maxSanityBonus)*100)+"%";el("goldNumH").textContent=S.gold;el("depthNum").textContent=ex.depth.toFixed(1);el("recordNum").textContent=S.maxDepthRecord.toFixed(1);const torchPct=ex.active?Math.max(0,ex.torch/ex.maxTorch*100):100;el("torchFill").style.height=torchPct+"%";el("torchPct").textContent=Math.round(torchPct);const flame=el("flame");flame.style.animationDuration=ex.active?(0.6+torchPct/100*1.2)+"s":"1.6s";flame.style.opacity=ex.active?(0.4+torchPct/100*0.6):1;el("expLayerLabel").textContent=LAYERS[ex.layerIndex]?LAYERS[ex.layerIndex].name:"???";el("expDepthMax").textContent=LAYERS[ex.layerIndex]?LAYERS[ex.layerIndex].maxDepth+"尺":"?";if(ex.itemsFound.length===0)el("expItemsBag").innerHTML=`<div style="color:var(--muted);font-size:10px;text-align:center;">暂无战利品</div>`;else el("expItemsBag").innerHTML=ex.itemsFound.map(item=>`<div class="row"><span class="${'rarity-'+item.rarity}">${item.name}</span></div>`).join("");const box=el("encounterBox");if(!ex.active){box.className="encounter empty";box.innerHTML="远征结束"}else if(!ex.monster){if(ex.event&&ex.event.type!=="narrative"){const ev=ex.event;box.className="encounter";box.innerHTML=`<div style="font-size:15px;color:var(--candle);margin-bottom:8px;">${ev.name||"……"}</div><div style="font-size:12px;color:var(--muted);margin-bottom:12px;">${ev.type==="curio"?"一件奇物出现在你面前。":ev.type==="trap"?"前方有危险的气息。":"一处可以歇脚的地方。"}</div><div style="display:flex;gap:8px;"><button class="small" onclick="resolveEvent('safe')" style="flex:1;">${ev.safe.text||"稳妥行事"}</button><button class="small danger" onclick="resolveEvent('risky')" style="flex:1;">${ev.risky.text||"冒险一试"}</button></div>`}else{box.className="encounter empty";box.innerHTML="回廊寂静无声…"}}else{box.className="encounter";const pct=Math.max(0,ex.monster.hp/ex.monster.maxHp*100);box.innerHTML=`<div class="monster-name">${ex.monster.name}</div><div class="monster-hp-wrap"><div class="monster-hp"><div style="width:${pct}%"></div></div><div class="monster-hp-num">${Math.max(0,Math.round(ex.monster.hp))}/${ex.monster.maxHp}</div></div>`}el("descendBtn").disabled=ex.active;el("retreatBtn").disabled=!ex.active;el("logBox").innerHTML=S.logs.map(l=>`<div class="entry ${l.cls}">${l.text}</div>`).join("");const skillBar=document.getElementById("skillBar");if(skillBar){const bloodrageBlock=h.race==="bear"&&h.sanity<h.maxSanity*0.3;const allSkills=[...SKILLS.filter(s=>!s.race||s.race===h.race)];skillBar.innerHTML=allSkills.map(sk=>{const onCd=ex.skillCooldowns[sk.id]&&ex.skillCooldowns[sk.id]>0;const cdText=onCd?` (${ex.skillCooldowns[sk.id]}s)`:"";let disabled=!ex.active||!ex.monster||bloodrageBlock;if(ex.active&&ex.monster&&!onCd&&!bloodrageBlock){if(sk.costType==="sanity"&&h.sanity<sk.cost)disabled=true;if(sk.costType==="torch"&&ex.torch<sk.cost)disabled=true;if(sk.costType==="hp"&&h.hp<=sk.cost)disabled=true}let cls="skill-btn";if(onCd)cls+=" on-cooldown";const hasBuff=ex.activeBuffs[sk.buffKey];if(hasBuff)cls+=" active-buff";if(sk.id==="allin")cls+=" danger";const text=onCd?sk.name+cdText:sk.name;return `<button class="${cls}" ${disabled?'disabled':''} onclick="useSkill('${sk.id}')">${sk.name}</button>`}).join("")}const consumableBar=document.getElementById("consumableBar");if(consumableBar){const inCombat=ex.active&&ex.monster;consumableBar.innerHTML=SHOP_ITEMS.map(item=>{const held=ex.consumables[item.id]||0;const combatOnly=(item.effect==="holyWater"||item.effect==="firebomb");const canUse=ex.active&&held>0&&(!combatOnly||inCombat);return `<button class="skill-btn" ${!canUse?'disabled':''} onclick="useConsumable('${item.id}')" title="${item.desc} (剩余 ${held})">${item.icon} ${held}</button>`}).join("")}document.getElementById("headerEyebrow").textContent="深 渊 · 探 索 · 生 存";document.getElementById("headerSub").textContent="火光摇曳，深渊在等待"}

function equipFromInv(idx){const item=S.inventory[idx];if(!item||item.unidentified||item.type==="material")return;const slotKey=item.type;if(!S.equipment.hasOwnProperty(slotKey))return;const unlockMap={weapon:1,body:1,hands:2,feet:3,head:5,waist:6,cloak:7,relic:8};if(S.equipSlots<(unlockMap[slotKey]||1))return;const old=S.equipment[slotKey];S.equipment[slotKey]=item;if(old){if(S.inventory.length>=getBagCapacity()){S.gold+=Math.floor(old.sellPrice||1);pushLog(`背包已满，换下的${old.name}自动出售。`,"dim")}else{S.inventory.splice(idx,1,old);pushLog(`将${old.name}换为${item.name}。`,"dim")}}else{S.inventory.splice(idx,1);pushLog(`装备了${item.name}。`,"dim")}render();save()}
function unequipItem(slotKey){const item=S.equipment[slotKey];if(!item)return;if(S.inventory.length>=getBagCapacity()){S.gold+=Math.floor(item.sellPrice||1);S.equipment[slotKey]=null;pushLog(`背包已满，卸下${item.name}后自动出售，获得 ${Math.floor(item.sellPrice||1)} 金。`,"dim")}else{S.inventory.push(item);S.equipment[slotKey]=null;pushLog(`卸下了${item.name}。`,"dim")}render();save()}
function repairEquipment(slotKey){const item=S.equipment[slotKey];const cost=repairCost(item);if(cost<=0||S.gold<cost)return;S.gold-=cost;item.durability=item.maxDurability;pushLog(`修复了${item.name}，花费 ${cost} 金。`,"dim");render();save()}
function sellItem(idx){const item=S.inventory[idx];if(!item)return;S.gold+=item.sellPrice||1;pushLog(`出售了${item.name}，获得 ${item.sellPrice||1} 金。`,"dim");S.inventory.splice(idx,1);render();save()}
function discardItem(idx){S.inventory.splice(idx,1);pushLog("丢弃了一件物品。","dim");render();save()}
function identifyItem(itemId){const item=S.inventory.find(i=>i.id===itemId);if(!item||!item.unidentified)return;const smithMul=S.hero.race==="dwarf"?0.7:1;const cost=Math.round((item.sellPrice||10)*0.4*smithMul);if(S.gold<cost){pushLog("金币不足，无法鉴定。","warn");render();save();return}S.gold-=cost;item.unidentified=false;if(item.templateId){const tpl=EQUIP_TEMPLATES.find(e=>e.id===item.templateId);if(tpl)item.name=tpl.name}pushLog(`鉴定完成——是「${item.name}」！`,"good");render();save()}
function craftItem(recipeId){const recipe=CRAFT_RECIPES.find(r=>r.id===recipeId);if(!recipe||!S.unlockedLayers.includes(recipe.needLayer))return;if(!recipe.materials.every(m=>countMaterial(m.mid)>=m.qty))return;const smithMul=S.hero.race==="dwarf"?0.7:1;const craftCost=Math.round(recipe.cost*smithMul);if(S.gold<craftCost||S.inventory.length>=getBagCapacity())return;recipe.materials.forEach(m=>{let q=S.hero.race==="dwarf"?Math.max(1,m.qty-1):m.qty;while(q>0){const idx=S.inventory.findLastIndex(i=>i.templateId===m.mid);if(idx>=0){S.inventory.splice(idx,1);q--}else break}});S.gold-=craftCost;const tpl=EQUIP_TEMPLATES.find(e=>e.id===recipe.result.tid);if(tpl){const item={id:tpl.id+"_craft_"+Date.now()+"_"+Math.random().toString(36).slice(2,6),templateId:tpl.id,name:tpl.name,type:tpl.type,rarity:tpl.rarity,stats:{...tpl.baseStats},durability:tpl.baseDura,maxDurability:tpl.baseDura,sellPrice:tpl.baseVal,unidentified:false};S.inventory.push(item);pushLog(`打造完成——获得「${item.name}」！`,"good");S.craftsMade=(S.craftsMade||0)+1;if(S.craftsMade>=3)unlockRace("dwarf")}render();save()}
function claimQuestById(idx){claimQuest(S.activeQuests[idx]);render();save()}
function abandonQuest(idx){pushLog(`放弃了任务「${S.activeQuests[idx].name}」。`,"dim");S.activeQuests.splice(idx,1);render();save()}
function selectLayer(idx){if(!S.unlockedLayers.includes(idx))return;S.selectedLayer=idx;renderCamp();save()}
function returnToCamp(){if(!S.expedition.active)return;endExpedition("manual",0,0);render();save()}
function getEquipName(tid){const t=EQUIP_TEMPLATES.find(e=>e.id===tid);return t?t.name:"?"}
function getMaterialName(mid){const t=MATERIAL_TEMPLATES.find(m=>m.id===mid);return t?t.name:"?"}
function countMaterial(mid){return S.inventory.filter(i=>i.templateId===mid&&!i.unidentified).length}
function updateQuestKill(monsterName){S.activeQuests.forEach(q=>{if(q.type==="kill"&&q.monster===monsterName)q.progress=Math.min(q.count,(q.progress||0)+1)})}
function updateQuestOnEnd(ex){S.activeQuests.forEach(q=>{if(q.type==="depth"&&ex.maxDepthReached>=q.target)q.progress=q.count||1;if(q.type==="survive"&&ex.surviveMinutes>=q.minutes)q.progress=q.count||1;if(q.type==="collect"){const found=ex.itemsFound.filter(i=>i.name===q.material).length;q.progress=Math.min(q.count,(q.progress||0)+found)}})}
function checkQuestCompletion(){S.activeQuests=S.activeQuests.filter(q=>{if(q.expiresAt&&q.expiresAt<Date.now()&&!q.completed){pushLog(`任务「${q.name}」已过期。`,"dim");return false}return true});S.activeQuests.forEach(q=>{if(!q.completed&&q.progress>=(q.count||1))q.completed=true})}
function generateQuest(){const now=Date.now();const available=QUEST_POOL.filter(q=>{if(S.activeQuests.find(aq=>aq.poolId===q.id))return false;if(q.needLayer&&!S.unlockedLayers.includes(q.needLayer))return false;return true});if(available.length===0)return null;const tpl=available[Math.floor(Math.random()*available.length)];return{poolId:tpl.id,name:tpl.name,desc:tpl.desc,type:tpl.type,monster:tpl.monster||null,count:tpl.count||1,target:tpl.target||0,material:tpl.material||null,minutes:tpl.minutes||0,progress:0,completed:false,reward:{gold:tpl.gold,itemTid:tpl.itemReward?tpl.itemReward.tid:null},expiresAt:now+(tpl.timeLimit||15)*60*1000,needLayer:tpl.needLayer||0}}
function claimQuest(q){if(!q.completed)return;S.gold+=q.reward.gold;pushLog(`完成任务「${q.name}」，获得 ${q.reward.gold} 金。`,"good");if(q.reward.itemTid){const tpl=EQUIP_TEMPLATES.find(e=>e.id===q.reward.itemTid);if(tpl&&S.inventory.length<getBagCapacity()){const item={id:tpl.id+"_quest_"+Date.now()+"_"+Math.random().toString(36).slice(2,6),templateId:tpl.id,name:tpl.name,type:tpl.type,rarity:tpl.rarity,stats:{...tpl.baseStats},durability:tpl.baseDura,maxDurability:tpl.baseDura,sellPrice:tpl.baseVal,unidentified:false};S.inventory.push(item);pushLog(`获得了 ${tpl.name}！`,"good")}}S.completedQuestIds.push(q.poolId);S.activeQuests=S.activeQuests.filter(aq=>aq!==q);S.questRefreshAt=Date.now()+2*60*1000}
function refreshQuests(){if(S.activeQuests.length>=3)return;const need=3-S.activeQuests.length;for(let i=0;i<need;i++){const q=generateQuest();if(q)S.activeQuests.push(q)}}

function switchToCamp(){document.body.classList.remove("in-expedition");renderCampTab(S._campTab||"prep")}
function switchToExpedition(){document.body.classList.add("in-expedition")}

function repairCost(item){if(!item||item.durability>=item.maxDurability)return 0;const rarityData=RARITY[item.rarity]||RARITY.common;const missing=item.maxDurability-item.durability;return Math.max(1,Math.round(missing*0.02*(item.sellPrice||5)*rarityData.craftCostMul))}

function render(){if(document.body.classList.contains("in-expedition"))renderExpedition();else renderCamp()}
function renderCamp(){el("goldNumH").textContent=S.gold;const tab=S._campTab||"prep";renderPrep();renderQuestBoard();renderShop();renderSmith(tab==="smith"?S._smithTab||"sell":"sell");renderAbyssGate();renderChurch();renderWarehouse();renderSettings();renderTavern();document.getElementById("headerEyebrow").textContent="营 地 · 整 备 · 出 征";document.getElementById("headerSub").textContent="火尽人归，深处不留光"}
function renderCampTab(tab){S._campTab=tab;document.querySelectorAll(".nav-tab").forEach(b=>b.classList.remove("active"));const btn=document.querySelector(`.nav-tab[data-tab="${tab}"]`);if(btn)btn.classList.add("active");document.querySelectorAll("#camp-view .tab-content").forEach(p=>p.classList.remove("active"));const panel=document.getElementById("tab-"+tab);if(panel)panel.classList.add("active");renderCamp()}

function renderPrep(){const eq=S.equipment,maxSlots=S.equipSlots;const allSlots={weapon:{label:"🗡 武器",side:"attack",desc:"攻击力·暴击",unlockAt:1},hands:{label:"✋ 手部",side:"attack",desc:"暴击率·攻速",unlockAt:2},relic:{label:"🔮 圣物",side:"attack",desc:"被动·复活",unlockAt:8},cloak:{label:"🧥 披风",side:"attack",desc:"火把·黑暗",unlockAt:7},head:{label:"🎩 头部",side:"defense",desc:"神智抗性",unlockAt:5},body:{label:"🛡 躯干",side:"defense",desc:"防御力·生命",unlockAt:1},waist:{label:"🎽 腰部",side:"defense",desc:"背包扩容",unlockAt:6},feet:{label:"👢 足部",side:"defense",desc:"闪避·移动",unlockAt:3}};const stats=calcHeroStats();const totalBag=S.bagCapacity+stats.bagSlots;const raceNames={human:"👤 人类",elf:"🧝 精灵",bear:"🐻 熊人",dwarf:"⛏️ 矮人"};function slotHTML(key){const cfg=allSlots[key];const locked=maxSlots<cfg.unlockAt;const lockHints={5:"到达中层甬道解锁",6:"到达中层甬道解锁",7:"到达深层墓室解锁",8:"到达绝渊回廊解锁"};const item=eq[key];if(locked)return `<div class="equip-slot" style="opacity:0.4"><span class="slot-label">${cfg.label}</span><span class="slot-empty">🔒 ${lockHints[cfg.unlockAt]||"未解锁"}</span></div>`;if(item){const durPct=item.maxDurability>0?Math.round(item.durability/item.maxDurability*100):100;const warnClass=durPct<25?"durability-warn":"";return `<div class="equip-slot ${warnClass}"><div><span class="slot-label">${cfg.label}</span><span style="font-size:9px;color:var(--muted);"> ${cfg.desc}</span><br><span class="slot-item ${'rarity-'+item.rarity}">${item.name}</span><span style="font-size:10px;color:${durPct<25?'var(--blood-bright)':'var(--muted)'};"> 耐久 ${Math.round(item.durability)}/${item.maxDurability}</span></div><div class="slot-actions">${item.durability<item.maxDurability?`<button class="small" onclick="repairEquipment('${key}');event.stopPropagation();">修 ${repairCost(item)}金</button>`:""}<button class="small danger" onclick="unequipItem('${key}');event.stopPropagation();">卸</button></div></div>`}return `<div class="equip-slot"><span class="slot-label">${cfg.label}</span><span style="font-size:9px;color:var(--muted);"> ${cfg.desc}</span><span class="slot-empty">空</span></div>`}const attackSlots=["weapon","hands","relic","cloak"];const defenseSlots=["head","body","waist","feet"];el("equipSlots").innerHTML=`<div style="font-size:12px;color:var(--candle-dim);margin-bottom:8px;">种族：${raceNames[S.hero.race]||"👤 人类"}</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;"><div><div style="text-align:center;font-size:11px;color:var(--candle-dim);letter-spacing:0.15em;margin-bottom:6px;border-bottom:1px solid var(--line);padding-bottom:4px;">— 攻 势 —</div>${attackSlots.map(k=>slotHTML(k)).join("")}</div><div><div style="text-align:center;font-size:11px;color:var(--candle-dim);letter-spacing:0.15em;margin-bottom:6px;border-bottom:1px solid var(--line);padding-bottom:4px;">— 守 御 —</div>${defenseSlots.map(k=>slotHTML(k)).join("")}</div></div>`;const inv=S.inventory;el("invCount").textContent=inv.length+"/"+totalBag;if(inv.length===0)el("invPanel").innerHTML=`<div style="color:var(--muted);font-size:12px;text-align:center;padding:20px;">背包空空如也<br><span style="font-size:10px;">深入深渊，获取战利品</span></div>`;else el("invPanel").innerHTML=inv.map((item,i)=>{const canEquip=!item.unidentified&&item.type!=="material"&&maxSlots>=(allSlots[item.type]?allSlots[item.type].unlockAt:99);const durText=item.type!=="material"?`<span class="inv-dur">${Math.round(item.durability)}/${item.maxDurability}</span>`:"";return `<div class="inv-row"><span class="inv-name ${'rarity-'+item.rarity}">${item.unidentified?'🔍 ':''}${item.name}</span>${durText}<span class="inv-act">${canEquip?`<button class="small" onclick="equipFromInv(${i})">装备</button>`:""}<button class="small" style="border-color:var(--candle);color:var(--candle);" onclick="sellItem(${i})">出售 ${item.sellPrice}金</button><button class="small danger" onclick="discardItem(${i})">丢弃</button></span></div>`}).join("")}

function renderQuestBoard(){checkQuestCompletion();const now=Date.now();if(S.activeQuests.length<3&&(!S.questRefreshAt||now>=S.questRefreshAt)){refreshQuests();S.questRefreshAt=now+2*60*1000}let html="";S.activeQuests.forEach((q,idx)=>{const remaining=q.expiresAt?Math.max(0,Math.floor((q.expiresAt-now)/1000)):0;const min=Math.floor(remaining/60),sec=remaining%60;const urgent=remaining<120;const cardClass=q.completed?"completed":(remaining<=0?"failed":"");html+=`<div class="quest-card ${cardClass}"><div class="q-header"><span class="q-name">${q.completed?'✅ ':''}${q.name}</span><span class="q-timer ${urgent?'urgent':'normal'}">⏱ ${min}:${sec.toString().padStart(2,'0')}</span></div><div class="q-desc">${q.desc}</div><div class="q-progress">进度：${q.progress||0}/${q.count||1}${q.type==='survive'?' 分钟':''}</div><div class="q-reward">🎁 ${q.reward.gold}金${q.reward.itemTid?' + '+getEquipName(q.reward.itemTid):''}</div><div class="q-actions">${q.completed?`<button class="primary small" onclick="claimQuestById(${idx})">领取奖励</button>`:`<button class="small danger" onclick="abandonQuest(${idx})">放弃</button>`}</div></div>`});if(S.activeQuests.length===0)html=`<div style="color:var(--muted);text-align:center;padding:20px;">暂无悬赏令<br><span style="font-size:10px;">等待任务板刷新……</span></div>`;el("questList").innerHTML=html;const secToRefresh=S.questRefreshAt?Math.max(0,Math.floor((S.questRefreshAt-now)/1000)):0;el("questRefreshInfo").textContent=`刷新倒计时: ${Math.floor(secToRefresh/60)}:${(secToRefresh%60).toString().padStart(2,'0')}`}

function renderShop(){let html="";SHOP_ITEMS.forEach(item=>{const held=S.expedition.consumables[item.id]||0;const canBuy=!S.expedition.active&&S.gold>=item.price&&held<item.maxCarry;html+=`<div class="shop-card" style="flex:1;min-width:140px;background:var(--panel-2);border:1px solid var(--line);border-radius:3px;padding:12px;text-align:center;"><div style="font-size:22px;">${item.icon}</div><div style="font-size:14px;color:var(--moon);margin:4px 0;">${item.name}</div><div style="font-size:10px;color:var(--muted);margin-bottom:6px;">${item.desc}</div><div style="font-size:10px;color:var(--muted);margin-bottom:6px;">携带: ${held}/${item.maxCarry}</div><button class="small primary" ${!canBuy?'disabled':''} onclick="buyConsumable('${item.id}')">${item.price}金</button></div>`});el("shopItems").innerHTML=html}

function renderSmith(subtab){S._smithTab=subtab;document.querySelectorAll(".smith-tab").forEach(b=>b.classList.remove("active"));const btn=document.querySelector(`.smith-tab[data-smith="${subtab}"]`);if(btn)btn.classList.add("active");document.querySelectorAll(".smith-content").forEach(p=>p.classList.remove("active"));const panel=document.getElementById("smith-"+subtab);if(panel)panel.classList.add("active");el("identifyBadge").textContent=S.inventory.filter(i=>i.unidentified).length>0?`(${S.inventory.filter(i=>i.unidentified).length})`:"";const smithMul=S.hero.race==="dwarf"?0.7:1;let sellHtml="";if(S.inventory.length===0)sellHtml=`<div style="color:var(--muted);text-align:center;padding:20px;">没有可出售的物品</div>`;else S.inventory.forEach((item,i)=>{sellHtml+=`<div class="sell-row"><span class="${'rarity-'+item.rarity}">${item.unidentified?'🔍 ':''}${item.name} ${item.type!=="material"?`[${Math.round(item.durability)}/${item.maxDurability}]`:''}</span><span class="sell-price">${item.sellPrice}金</span><button class="small" style="border-color:var(--candle);color:var(--candle);" onclick="sellItem(${i})">出售</button></div>`});el("smith-sell").innerHTML=sellHtml;let idHtml="";const unidItems=S.inventory.filter(i=>i.unidentified);if(unidItems.length===0)idHtml=`<div style="color:var(--muted);text-align:center;padding:20px;">没有待鉴定的物品<br><span style="font-size:10px;">深渊中偶尔能发现需要鉴定的装备</span></div>`;else unidItems.forEach(item=>{const cost=Math.round((item.sellPrice||10)*0.4*smithMul);idHtml+=`<div class="sell-row"><span>🔍 ${item.name}</span><span class="sell-price">鉴定费 ${cost}金</span><button class="small primary" onclick="identifyItem('${item.id}')">鉴定</button></div>`});el("smith-identify").innerHTML=idHtml;let craftHtml=`<table class="craft-table"><tr><th>名称</th><th>类型</th><th>稀有度</th><th>材料</th><th>金币</th><th></th></tr>`;CRAFT_RECIPES.forEach(recipe=>{const locked=!S.unlockedLayers.includes(recipe.needLayer);const resultTpl=EQUIP_TEMPLATES.find(e=>e.id===recipe.result.tid);const name=resultTpl?resultTpl.name:recipe.name;const rarity=resultTpl?resultTpl.rarity:"common";const type=resultTpl?resultTpl.type:"?";const matsText=recipe.materials.map(m=>`${getMaterialName(m.mid)}×${m.qty}`).join(" + ");const craftCost=Math.round(recipe.cost*smithMul);const canCraft=!locked&&recipe.materials.every(m=>countMaterial(m.mid)>=m.qty)&&S.gold>=craftCost&&S.inventory.length<getBagCapacity();craftHtml+=`<tr class="${locked?'locked-row':''}"><td class="${'rarity-'+rarity}">${name}</td><td>${slotLabel(type)}</td><td>${RARITY[rarity]?RARITY[rarity].name:'?'}</td><td>${matsText}</td><td>${craftCost}金${smithMul<1?' (-30%)':''}</td><td>${locked?`<span style="font-size:10px;color:var(--muted);">需要${LAYERS[recipe.needLayer].name}</span>`:`<button class="small primary" ${!canCraft?'disabled':''} onclick="craftItem('${recipe.id}')">打造</button>`}</td></tr>`});craftHtml+=`</table>`;el("smith-craft").innerHTML=craftHtml}

function renderAbyssGate(){let html="";LAYERS.forEach((layer,i)=>{const unlocked=S.unlockedLayers.includes(i);const selected=S.selectedLayer===i;html+=`<div class="layer-card ${unlocked?'':'locked'} ${selected?'selected':''}" ${unlocked?`onclick="selectLayer(${i})"`:''}><div class="l-name">${unlocked?'🔓':'🔒'} ${layer.name}</div><div class="l-depth">${layer.startDepth} - ${layer.maxDepth>=999?'∞':layer.maxDepth} 尺</div><div class="l-monsters">🐉 ${layer.monsters.slice(0,3).join(' · ')}${layer.monsters.length>3?' …':''}</div><div class="l-danger">危险等级：${layer.danger}</div>${!unlocked?`<div class="l-unlock">${layer.unlockMsg||'?'}</div>`:''}${layer.unlockBonus?`<div class="l-unlock" style="color:var(--candle-dim);">${layer.unlockBonus}</div>`:''}</div>`});el("layerCards").innerHTML=html;const layer=LAYERS[S.selectedLayer];const unlocked=S.unlockedLayers.includes(S.selectedLayer);el("abyssAction").innerHTML=unlocked?`<button class="primary" style="font-size:16px;padding:12px 40px;" onclick="startExpedition(${S.selectedLayer})">⚔️ 从「${layer.name}」出征</button>`:`<span style="color:var(--muted);">该层级尚未解锁</span>`}

function renderChurch(){const now=Date.now();const onCooldown=S.prayerCooldown>now;const remaining=onCooldown?S.prayerCooldown-now:0;const hrs=Math.floor(remaining/3600000);const mins=Math.floor((remaining%3600000)/60000);if(S.activeBlessing){el("churchStatus").innerHTML=`<span style="color:var(--candle);">当前祝福生效中：</span>`;el("churchBuff").innerHTML=`<span style="font-size:18px;">${S.activeBlessing.icon} <strong style="color:var(--candle);">${S.activeBlessing.name}</strong></span><br><span style="font-size:12px;color:var(--muted);">${S.activeBlessing.desc}（下次远征生效）</span>`;el("prayBtn").disabled=true;el("prayBtn").textContent="祝福已就绪，出征吧"}else if(onCooldown){el("churchStatus").innerHTML=`<span style="color:var(--muted);">祷告后需静候神明的回应……</span>`;el("churchBuff").innerHTML=`<span style="font-size:13px;color:var(--muted);">冷却剩余：</span><span style="font-size:16px;color:var(--sanity);">${hrs}时${mins}分</span>`;el("prayBtn").disabled=true;el("prayBtn").textContent=`⏳ ${hrs}时${mins}分后可祈祷`}else{el("churchStatus").innerHTML=`<span style="color:var(--muted);">在深渊礼拜堂中静心祈祷，祈求神明的眷顾。</span>`;el("churchBuff").innerHTML=`<span style="font-size:12px;color:var(--muted);">可能获得的祝福：</span><br><span style="font-size:11px;color:var(--muted);">${BLESSINGS.map(b=>b.icon+b.name).join(' · ')}</span>`;el("prayBtn").disabled=false;el("prayBtn").textContent="🕯️ 祈 祷"}const s=calcHeroStats();const effMax=S.hero.maxSanity+s.maxSanityBonus;const cost=Math.ceil((effMax-S.hero.sanity)*1.5);const canRestore=S.hero.sanity<effMax&&S.gold>=cost;el("churchRestore").innerHTML=`<span style="font-size:12px;color:var(--muted);">恢复神智 · ${S.hero.sanity>=effMax?'神智已满':cost+' 金'}</span>`;const rstBtn=document.getElementById("restoreSanityBtn");if(rstBtn){rstBtn.disabled=!canRestore;rstBtn.textContent=S.hero.sanity>=effMax?"🙏 神智已满":`🙏 静心祈祷 · ${cost}金`}}
function doPray(){if(S.prayerCooldown>Date.now()||S.activeBlessing)return;const b=BLESSINGS[Math.floor(Math.random()*BLESSINGS.length)];S.activeBlessing={type:b.id,name:b.name,desc:b.desc,icon:b.icon,apply:b.apply};S.prayerCooldown=Date.now()+3*60*60*1000;pushLog(`⛪ 你在礼拜堂中虔诚祈祷，获得了「${b.name}」——${b.desc}`,"good");render();save()}
function restoreSanity(){const s=calcHeroStats();const effMax=S.hero.maxSanity+s.maxSanityBonus;const cost=Math.ceil((effMax-S.hero.sanity)*1.5);if(S.hero.sanity>=effMax||S.gold<cost)return;S.gold-=cost;S.hero.sanity=effMax;pushLog("你在残烛前静坐良久，心神渐渐安定。","good");render();save()}

function warehouseUpgradeCost(){const level=(S.warehouseSlots-20)/5;return Math.round(100*Math.pow(1.5,level))}
function upgradeWarehouse(){if(S.warehouseSlots>=50)return;const cost=warehouseUpgradeCost();if(S.gold<cost)return;S.gold-=cost;S.warehouseSlots+=5;pushLog(`📦 秘库扩容至 ${S.warehouseSlots} 格，花费 ${cost} 金。`,"good");render();save()}
function depositItem(idx){const item=S.inventory[idx];if(!item||item.unidentified||S.warehouse.length>=S.warehouseSlots)return;if(item.type==="material"&&item.templateId){const existing=S.warehouse.find(w=>w.templateId===item.templateId);if(existing&&existing.qty!==undefined){existing.qty+=1;S.inventory.splice(idx,1);render();save();return}S.warehouse.push({...item,qty:1})}else S.warehouse.push(item);S.inventory.splice(idx,1);render();save()}
function withdrawItem(whIdx){const item=S.warehouse[whIdx];if(!item||S.inventory.length>=getBagCapacity())return;if(item.qty!==undefined&&item.qty>1){const single={...item};delete single.qty;S.inventory.push(single);item.qty-=1;if(item.qty<=0)S.warehouse.splice(whIdx,1)}else{S.inventory.push(item);S.warehouse.splice(whIdx,1)}render();save()}
function renderWarehouse(){const wh=S.warehouse,inv=S.inventory;el("whCount").textContent=wh.length+"/"+S.warehouseSlots;if(S.warehouseSlots>=50)el("whUpgradeRow").innerHTML=`<span style="font-size:11px;color:var(--candle-dim);">秘库已满级 (50格)</span>`;else{const cost=warehouseUpgradeCost();el("whUpgradeRow").innerHTML=`<button class="small" ${S.gold<cost?'disabled':''} onclick="upgradeWarehouse()">扩容 +5格 · ${cost}金</button>`}if(wh.length===0)el("whPanel").innerHTML=`<div style="color:var(--muted);font-size:11px;text-align:center;padding:16px;">仓库空空如也</div>`;else el("whPanel").innerHTML=wh.map((item,i)=>{const name=item.name+(item.qty>1?` ×${item.qty}`:"");const sub=item.type!=="material"?`<span class="inv-dur">${Math.round(item.durability)}/${item.maxDurability}</span>`:"";return `<div class="inv-row"><span class="inv-name ${'rarity-'+item.rarity}">${name}</span>${sub}<span class="inv-act"><button class="small" onclick="withdrawItem(${i})">取出</button></span></div>`}).join("");if(inv.length===0)el("whInvPanel").innerHTML=`<div style="color:var(--muted);font-size:11px;text-align:center;padding:12px;">背包空空如也</div>`;else el("whInvPanel").innerHTML=inv.map((item,i)=>{const canDeposit=!item.unidentified&&wh.length<S.warehouseSlots;return `<div class="inv-row"><span class="inv-name ${'rarity-'+item.rarity}">${item.unidentified?'🔍 ':''}${item.name}</span><span class="inv-dur">${item.type!=="material"?Math.round(item.durability)+'/'+item.maxDurability:''}</span><span class="inv-act"><button class="small" ${!canDeposit?'disabled':''} onclick="depositItem(${i})">${item.unidentified?'🔍鉴定后':'存入'}</button></span></div>`}).join("")}

function confirmDeleteSave(){showModal("确认删除存档","此操作将永久删除你的所有进度，包括金币、装备、怪物志和最深记录。此操作不可撤销。",[{label:"取消",cls:"",action:"hideModal()"},{label:"确认删除",cls:"danger",action:"deleteSave()"}])}
function deleteSave(){S._deleting=true;localStorage.removeItem(SAVE_KEY);hideModal();location.reload()}
function renderSettings(){const el2=document.getElementById("settingsStats");if(el2)el2.innerHTML=`最深记录：<span style="color:var(--candle);">${S.maxDepthRecord.toFixed(1)}</span> 尺<br>持有金币：<span style="color:var(--candle);">${S.gold}</span><br>怪物志：<span style="color:var(--candle);">${Object.keys(S.bestiary).length}</span> 种<br>遗物收集：<span style="color:var(--candle);">${Object.keys(S.relicsOwned).length}</span> / ${RELICS.length}<br>最深层级：<span style="color:var(--candle);">${S.unlockedLayers.length>0?LAYERS[Math.max(...S.unlockedLayers)].name:'浅层回廊'}</span><br>当前种族：<span style="color:var(--candle);">${({human:'👤 人类',elf:'🧝 精灵',bear:'🐻 熊人',dwarf:'⛏️ 矮人'})[S.hero.race]||'???'}</span>`}

function renderTavern(){el("tavernRecord").textContent=S.maxDepthRecord.toFixed(1)}

function renderExpedition(){const ex=S.expedition,stats=calcHeroStats(),h=S.hero;const raceNames={human:"👤 人类",elf:"🧝 精灵",bear:"🐻 熊人",dwarf:"⛏️ 矮人"};el("expRace").textContent=raceNames[h.race]||"👤 人类";el("expLayerName").textContent=LAYERS[ex.layerIndex]?LAYERS[ex.layerIndex].name:"???";el("expCarriedGold").textContent=ex.carriedGold||0;el("hpNum").textContent=`${Math.max(0,Math.round(h.hp))} / ${stats.maxHp}`;el("hpFill").style.width=Math.max(0,(h.hp/stats.maxHp*100))+"%";el("atkNum").textContent=stats.atk;el("defNum").textContent=stats.def;el("dodgeNum").textContent=Math.round(stats.dodge*100)+"%";el("sanityNum").textContent=Math.round(h.sanity)+"/"+(h.maxSanity+stats.maxSanityBonus);el("sanityFill").style.width=(h.sanity/(h.maxSanity+stats.maxSanityBonus)*100)+"%";el("goldNumH").textContent=S.gold;el("depthNum").textContent=ex.depth.toFixed(1);el("recordNum").textContent=S.maxDepthRecord.toFixed(1);const torchPct=ex.active?Math.max(0,ex.torch/ex.maxTorch*100):100;el("torchFill").style.height=torchPct+"%";el("torchPct").textContent=Math.round(torchPct);const flame=el("flame");flame.style.animationDuration=ex.active?(0.6+torchPct/100*1.2)+"s":"1.6s";flame.style.opacity=ex.active?(0.4+torchPct/100*0.6):1;el("expLayerLabel").textContent=LAYERS[ex.layerIndex]?LAYERS[ex.layerIndex].name:"???";el("expDepthMax").textContent=LAYERS[ex.layerIndex]?LAYERS[ex.layerIndex].maxDepth+"尺":"?";if(ex.itemsFound.length===0)el("expItemsBag").innerHTML=`<div style="color:var(--muted);font-size:10px;text-align:center;">暂无战利品</div>`;else el("expItemsBag").innerHTML=ex.itemsFound.map(item=>`<div class="row"><span class="${'rarity-'+item.rarity}">${item.name}</span></div>`).join("");const box=el("encounterBox");if(!ex.active){box.className="encounter empty";box.innerHTML="远征结束"}else if(!ex.monster){if(ex.event&&ex.event.type!=="narrative"){const ev=ex.event;box.className="encounter";box.innerHTML=`<div style="font-size:15px;color:var(--candle);margin-bottom:8px;">${ev.name||"……"}</div><div style="font-size:12px;color:var(--muted);margin-bottom:12px;">${ev.type==="curio"?"一件奇物出现在你面前。":ev.type==="trap"?"前方有危险的气息。":"一处可以歇脚的地方。"}</div><div style="display:flex;gap:8px;"><button class="small" onclick="resolveEvent('safe')" style="flex:1;">${ev.safe.text||"稳妥行事"}</button><button class="small danger" onclick="resolveEvent('risky')" style="flex:1;">${ev.risky.text||"冒险一试"}</button></div>`}else{box.className="encounter empty";box.innerHTML="回廊寂静无声…"}}else{box.className="encounter";const pct=Math.max(0,ex.monster.hp/ex.monster.maxHp*100);box.innerHTML=`<div class="monster-name">${ex.monster.name}</div><div class="monster-hp-wrap"><div class="monster-hp"><div style="width:${pct}%"></div></div><div class="monster-hp-num">${Math.max(0,Math.round(ex.monster.hp))}/${ex.monster.maxHp}</div></div>`}el("descendBtn").disabled=ex.active;el("retreatBtn").disabled=!ex.active;el("logBox").innerHTML=S.logs.map(l=>`<div class="entry ${l.cls}">${l.text}</div>`).join("");const skillBar=document.getElementById("skillBar");if(skillBar){const bloodrageBlock=h.race==="bear"&&h.sanity<h.maxSanity*0.3;const allSkills=[...SKILLS.filter(s=>!s.race||s.race===h.race)];skillBar.innerHTML=allSkills.map(sk=>{const onCd=ex.skillCooldowns[sk.id]&&ex.skillCooldowns[sk.id]>0;const cdText=onCd?` (${ex.skillCooldowns[sk.id]}s)`:"";let disabled=!ex.active||!ex.monster||bloodrageBlock;if(ex.active&&ex.monster&&!onCd&&!bloodrageBlock){if(sk.costType==="sanity"&&h.sanity<sk.cost)disabled=true;if(sk.costType==="torch"&&ex.torch<sk.cost)disabled=true;if(sk.costType==="hp"&&h.hp<=sk.cost)disabled=true}let cls="skill-btn";if(onCd)cls+=" on-cooldown";const hasBuff=ex.activeBuffs[sk.buffKey];if(hasBuff)cls+=" active-buff";if(sk.id==="allin")cls+=" danger";const text=onCd?sk.name+cdText:sk.name;return `<button class="${cls}" ${disabled?'disabled':''} onclick="useSkill('${sk.id}')">${sk.name}</button>`}).join("")}const consumableBar=document.getElementById("consumableBar");if(consumableBar){const inCombat=ex.active&&ex.monster;consumableBar.innerHTML=SHOP_ITEMS.map(item=>{const held=ex.consumables[item.id]||0;const combatOnly=(item.effect==="holyWater"||item.effect==="firebomb");const canUse=ex.active&&held>0&&(!combatOnly||inCombat);return `<button class="skill-btn" ${!canUse?'disabled':''} onclick="useConsumable('${item.id}')" title="${item.desc} (剩余 ${held})">${item.icon} ${held}</button>`}).join("")}document.getElementById("headerEyebrow").textContent="深 渊 · 探 索 · 生 存";document.getElementById("headerSub").textContent="火光摇曳，深渊在等待"}

function equipFromInv(idx){const item=S.inventory[idx];if(!item||item.unidentified||item.type==="material")return;const slotKey=item.type;if(!S.equipment.hasOwnProperty(slotKey))return;const unlockMap={weapon:1,body:1,hands:2,feet:3,head:5,waist:6,cloak:7,relic:8};if(S.equipSlots<(unlockMap[slotKey]||1))return;const old=S.equipment[slotKey];S.equipment[slotKey]=item;if(old){if(S.inventory.length>=getBagCapacity()){S.gold+=Math.floor(old.sellPrice||1);pushLog(`背包已满，换下的${old.name}自动出售。`,"dim")}else{S.inventory.splice(idx,1,old);pushLog(`将${old.name}换为${item.name}。`,"dim")}}else{S.inventory.splice(idx,1);pushLog(`装备了${item.name}。`,"dim")}render();save()}
function unequipItem(slotKey){const item=S.equipment[slotKey];if(!item)return;if(S.inventory.length>=getBagCapacity()){S.gold+=Math.floor(item.sellPrice||1);S.equipment[slotKey]=null;pushLog(`背包已满，卸下${item.name}后自动出售，获得 ${Math.floor(item.sellPrice||1)} 金。`,"dim")}else{S.inventory.push(item);S.equipment[slotKey]=null;pushLog(`卸下了${item.name}。`,"dim")}render();save()}
function repairEquipment(slotKey){const item=S.equipment[slotKey];const cost=repairCost(item);if(cost<=0||S.gold<cost)return;S.gold-=cost;item.durability=item.maxDurability;pushLog(`修复了${item.name}，花费 ${cost} 金。`,"dim");render();save()}
function sellItem(idx){const item=S.inventory[idx];if(!item)return;S.gold+=item.sellPrice||1;pushLog(`出售了${item.name}，获得 ${item.sellPrice||1} 金。`,"dim");S.inventory.splice(idx,1);render();save()}
function discardItem(idx){S.inventory.splice(idx,1);pushLog("丢弃了一件物品。","dim");render();save()}
function identifyItem(itemId){const item=S.inventory.find(i=>i.id===itemId);if(!item||!item.unidentified)return;const smithMul=S.hero.race==="dwarf"?0.7:1;const cost=Math.round((item.sellPrice||10)*0.4*smithMul);if(S.gold<cost){pushLog("金币不足，无法鉴定。","warn");render();save();return}S.gold-=cost;item.unidentified=false;if(item.templateId){const tpl=EQUIP_TEMPLATES.find(e=>e.id===item.templateId);if(tpl)item.name=tpl.name}pushLog(`鉴定完成——是「${item.name}」！`,"good");render();save()}
function craftItem(recipeId){const recipe=CRAFT_RECIPES.find(r=>r.id===recipeId);if(!recipe||!S.unlockedLayers.includes(recipe.needLayer))return;if(!recipe.materials.every(m=>countMaterial(m.mid)>=m.qty))return;const smithMul=S.hero.race==="dwarf"?0.7:1;const craftCost=Math.round(recipe.cost*smithMul);if(S.gold<craftCost||S.inventory.length>=getBagCapacity())return;recipe.materials.forEach(m=>{let q=S.hero.race==="dwarf"?Math.max(1,m.qty-1):m.qty;while(q>0){const idx=S.inventory.findLastIndex(i=>i.templateId===m.mid);if(idx>=0){S.inventory.splice(idx,1);q--}else break}});S.gold-=craftCost;const tpl=EQUIP_TEMPLATES.find(e=>e.id===recipe.result.tid);if(tpl){const item={id:tpl.id+"_craft_"+Date.now()+"_"+Math.random().toString(36).slice(2,6),templateId:tpl.id,name:tpl.name,type:tpl.type,rarity:tpl.rarity,stats:{...tpl.baseStats},durability:tpl.baseDura,maxDurability:tpl.baseDura,sellPrice:tpl.baseVal,unidentified:false};S.inventory.push(item);pushLog(`打造完成——获得「${item.name}」！`,"good");S.craftsMade=(S.craftsMade||0)+1;if(S.craftsMade>=3)unlockRace("dwarf")}render();save()}
function claimQuestById(idx){claimQuest(S.activeQuests[idx]);render();save()}
function abandonQuest(idx){pushLog(`放弃了任务「${S.activeQuests[idx].name}」。`,"dim");S.activeQuests.splice(idx,1);render();save()}
function selectLayer(idx){if(!S.unlockedLayers.includes(idx))return;S.selectedLayer=idx;renderCamp();save()}
function returnToCamp(){if(!S.expedition.active)return;endExpedition("manual",0,0);render();save()}
function getEquipName(tid){const t=EQUIP_TEMPLATES.find(e=>e.id===tid);return t?t.name:"?"}
function getMaterialName(mid){const t=MATERIAL_TEMPLATES.find(m=>m.id===mid);return t?t.name:"?"}
function countMaterial(mid){return S.inventory.filter(i=>i.templateId===mid&&!i.unidentified).length}
function updateQuestKill(monsterName){S.activeQuests.forEach(q=>{if(q.type==="kill"&&q.monster===monsterName)q.progress=Math.min(q.count,(q.progress||0)+1)})}
function updateQuestOnEnd(ex){S.activeQuests.forEach(q=>{if(q.type==="depth"&&ex.maxDepthReached>=q.target)q.progress=q.count||1;if(q.type==="survive"&&ex.surviveMinutes>=q.minutes)q.progress=q.count||1;if(q.type==="collect"){const found=ex.itemsFound.filter(i=>i.name===q.material).length;q.progress=Math.min(q.count,(q.progress||0)+found)}})}
function checkQuestCompletion(){S.activeQuests=S.activeQuests.filter(q=>{if(q.expiresAt&&q.expiresAt<Date.now()&&!q.completed){pushLog(`任务「${q.name}」已过期。`,"dim");return false}return true});S.activeQuests.forEach(q=>{if(!q.completed&&q.progress>=(q.count||1))q.completed=true})}
function generateQuest(){const now=Date.now();const available=QUEST_POOL.filter(q=>{if(S.activeQuests.find(aq=>aq.poolId===q.id))return false;if(q.needLayer&&!S.unlockedLayers.includes(q.needLayer))return false;return true});if(available.length===0)return null;const tpl=available[Math.floor(Math.random()*available.length)];return{poolId:tpl.id,name:tpl.name,desc:tpl.desc,type:tpl.type,monster:tpl.monster||null,count:tpl.count||1,target:tpl.target||0,material:tpl.material||null,minutes:tpl.minutes||0,progress:0,completed:false,reward:{gold:tpl.gold,itemTid:tpl.itemReward?tpl.itemReward.tid:null},expiresAt:now+(tpl.timeLimit||15)*60*1000,needLayer:tpl.needLayer||0}}
function claimQuest(q){if(!q.completed)return;S.gold+=q.reward.gold;pushLog(`完成任务「${q.name}」，获得 ${q.reward.gold} 金。`,"good");if(q.reward.itemTid){const tpl=EQUIP_TEMPLATES.find(e=>e.id===q.reward.itemTid);if(tpl&&S.inventory.length<getBagCapacity()){const item={id:tpl.id+"_quest_"+Date.now()+"_"+Math.random().toString(36).slice(2,6),templateId:tpl.id,name:tpl.name,type:tpl.type,rarity:tpl.rarity,stats:{...tpl.baseStats},durability:tpl.baseDura,maxDurability:tpl.baseDura,sellPrice:tpl.baseVal,unidentified:false};S.inventory.push(item);pushLog(`获得了 ${tpl.name}！`,"good")}}S.completedQuestIds.push(q.poolId);S.activeQuests=S.activeQuests.filter(aq=>aq!==q);S.questRefreshAt=Date.now()+2*60*1000}
function refreshQuests(){if(S.activeQuests.length>=3)return;const need=3-S.activeQuests.length;for(let i=0;i<need;i++){const q=generateQuest();if(q)S.activeQuests.push(q)}}

function switchToCamp(){document.body.classList.remove("in-expedition");renderCampTab(S._campTab||"prep")}
function switchToExpedition(){document.body.classList.add("in-expedition")}

function repairCost(item){if(!item||item.durability>=item.maxDurability)return 0;const rarityData=RARITY[item.rarity]||RARITY.common;const missing=item.maxDurability-item.durability;return Math.max(1,Math.round(missing*0.02*(item.sellPrice||5)*rarityData.craftCostMul))}

function render(){if(document.body.classList.contains("in-expedition"))renderExpedition();else renderCamp()}
function renderCamp(){el("goldNumH").textContent=S.gold;const tab=S._campTab||"prep";renderPrep();renderQuestBoard();renderShop();renderSmith(tab==="smith"?S._smithTab||"sell":"sell");renderAbyssGate();renderChurch();renderWarehouse();renderSettings();renderTavern();document.getElementById("headerEyebrow").textContent="营 地 · 整 备 · 出 征";document.getElementById("headerSub").textContent="火尽人归，深处不留光"}
function renderCampTab(tab){S._campTab=tab;document.querySelectorAll(".nav-tab").forEach(b=>b.classList.remove("active"));const btn=document.querySelector(`.nav-tab[data-tab="${tab}"]`);if(btn)btn.classList.add("active");document.querySelectorAll("#camp-view .tab-content").forEach(p=>p.classList.remove("active"));const panel=document.getElementById("tab-"+tab);if(panel)panel.classList.add("active");renderCamp()}

function renderPrep(){const eq=S.equipment,maxSlots=S.equipSlots;const allSlots={weapon:{label:"🗡 武器",side:"attack",desc:"攻击力·暴击",unlockAt:1},hands:{label:"✋ 手部",side:"attack",desc:"暴击率·攻速",unlockAt:2},relic:{label:"🔮 圣物",side:"attack",desc:"被动·复活",unlockAt:8},cloak:{label:"🧥 披风",side:"attack",desc:"火把·黑暗",unlockAt:7},head:{label:"🎩 头部",side:"defense",desc:"神智抗性",unlockAt:5},body:{label:"🛡 躯干",side:"defense",desc:"防御力·生命",unlockAt:1},waist:{label:"🎽 腰部",side:"defense",desc:"背包扩容",unlockAt:6},feet:{label:"👢 足部",side:"defense",desc:"闪避·移动",unlockAt:3}};const stats=calcHeroStats();const totalBag=S.bagCapacity+stats.bagSlots;const raceNames={human:"👤 人类",elf:"🧝 精灵",bear:"🐻 熊人",dwarf:"⛏️ 矮人"};function slotHTML(key){const cfg=allSlots[key];const locked=maxSlots<cfg.unlockAt;const lockHints={5:"到达中层甬道解锁",6:"到达中层甬道解锁",7:"到达深层墓室解锁",8:"到达绝渊回廊解锁"};const item=eq[key];if(locked)return `<div class="equip-slot" style="opacity:0.4"><span class="slot-label">${cfg.label}</span><span class="slot-empty">🔒 ${lockHints[cfg.unlockAt]||"未解锁"}</span></div>`;if(item){const durPct=item.maxDurability>0?Math.round(item.durability/item.maxDurability*100):100;const warnClass=durPct<25?"durability-warn":"";return `<div class="equip-slot ${warnClass}"><div><span class="slot-label">${cfg.label}</span><span style="font-size:9px;color:var(--muted);"> ${cfg.desc}</span><br><span class="slot-item ${'rarity-'+item.rarity}">${item.name}</span><span style="font-size:10px;color:${durPct<25?'var(--blood-bright)':'var(--muted)'};"> 耐久 ${Math.round(item.durability)}/${item.maxDurability}</span></div><div class="slot-actions">${item.durability<item.maxDurability?`<button class="small" onclick="repairEquipment('${key}');event.stopPropagation();">修 ${repairCost(item)}金</button>`:""}<button class="small danger" onclick="unequipItem('${key}');event.stopPropagation();">卸</button></div></div>`}return `<div class="equip-slot"><span class="slot-label">${cfg.label}</span><span style="font-size:9px;color:var(--muted);"> ${cfg.desc}</span><span class="slot-empty">空</span></div>`}const attackSlots=["weapon","hands","relic","cloak"];const defenseSlots=["head","body","waist","feet"];el("equipSlots").innerHTML=`<div style="font-size:12px;color:var(--candle-dim);margin-bottom:8px;">种族：${raceNames[S.hero.race]||"👤 人类"}</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;"><div><div style="text-align:center;font-size:11px;color:var(--candle-dim);letter-spacing:0.15em;margin-bottom:6px;border-bottom:1px solid var(--line);padding-bottom:4px;">— 攻 势 —</div>${attackSlots.map(k=>slotHTML(k)).join("")}</div><div><div style="text-align:center;font-size:11px;color:var(--candle-dim);letter-spacing:0.15em;margin-bottom:6px;border-bottom:1px solid var(--line);padding-bottom:4px;">— 守 御 —</div>${defenseSlots.map(k=>slotHTML(k)).join("")}</div></div>`;const inv=S.inventory;el("invCount").textContent=inv.length+"/"+totalBag;if(inv.length===0)el("invPanel").innerHTML=`<div style="color:var(--muted);font-size:12px;text-align:center;padding:20px;">背包空空如也<br><span style="font-size:10px;">深入深渊，获取战利品</span></div>`;else el("invPanel").innerHTML=inv.map((item,i)=>{const canEquip=!item.unidentified&&item.type!=="material"&&maxSlots>=(allSlots[item.type]?allSlots[item.type].unlockAt:99);const durText=item.type!=="material"?`<span class="inv-dur">${Math.round(item.durability)}/${item.maxDurability}</span>`:"";return `<div class="inv-row"><span class="inv-name ${'rarity-'+item.rarity}">${item.unidentified?'🔍 ':''}${item.name}</span>${durText}<span class="inv-act">${canEquip?`<button class="small" onclick="equipFromInv(${i})">装备</button>`:""}<button class="small" style="border-color:var(--candle);color:var(--candle);" onclick="sellItem(${i})">出售 ${item.sellPrice}金</button><button class="small danger" onclick="discardItem(${i})">丢弃</button></span></div>`}).join("")}

function renderQuestBoard(){checkQuestCompletion();const now=Date.now();if(S.activeQuests.length<3&&(!S.questRefreshAt||now>=S.questRefreshAt)){refreshQuests();S.questRefreshAt=now+2*60*1000}let html="";S.activeQuests.forEach((q,idx)=>{const remaining=q.expiresAt?Math.max(0,Math.floor((q.expiresAt-now)/1000)):0;const min=Math.floor(remaining/60),sec=remaining%60;const urgent=remaining<120;const cardClass=q.completed?"completed":(remaining<=0?"failed":"");html+=`<div class="quest-card ${cardClass}"><div class="q-header"><span class="q-name">${q.completed?'✅ ':''}${q.name}</span><span class="q-timer ${urgent?'urgent':'normal'}">⏱ ${min}:${sec.toString().padStart(2,'0')}</span></div><div class="q-desc">${q.desc}</div><div class="q-progress">进度：${q.progress||0}/${q.count||1}${q.type==='survive'?' 分钟':''}</div><div class="q-reward">🎁 ${q.reward.gold}金${q.reward.itemTid?' + '+getEquipName(q.reward.itemTid):''}</div><div class="q-actions">${q.completed?`<button class="primary small" onclick="claimQuestById(${idx})">领取奖励</button>`:`<button class="small danger" onclick="abandonQuest(${idx})">放弃</button>`}</div></div>`});if(S.activeQuests.length===0)html=`<div style="color:var(--muted);text-align:center;padding:20px;">暂无悬赏令<br><span style="font-size:10px;">等待任务板刷新……</span></div>`;el("questList").innerHTML=html;const secToRefresh=S.questRefreshAt?Math.max(0,Math.floor((S.questRefreshAt-now)/1000)):0;el("questRefreshInfo").textContent=`刷新倒计时: ${Math.floor(secToRefresh/60)}:${(secToRefresh%60).toString().padStart(2,'0')}`}

function renderShop(){let html="";SHOP_ITEMS.forEach(item=>{const held=S.expedition.consumables[item.id]||0;const canBuy=!S.expedition.active&&S.gold>=item.price&&held<item.maxCarry;html+=`<div class="shop-card" style="flex:1;min-width:140px;background:var(--panel-2);border:1px solid var(--line);border-radius:3px;padding:12px;text-align:center;"><div style="font-size:22px;">${item.icon}</div><div style="font-size:14px;color:var(--moon);margin:4px 0;">${item.name}</div><div style="font-size:10px;color:var(--muted);margin-bottom:6px;">${item.desc}</div><div style="font-size:10px;color:var(--muted);margin-bottom:6px;">携带: ${held}/${item.maxCarry}</div><button class="small primary" ${!canBuy?'disabled':''} onclick="buyConsumable('${item.id}')">${item.price}金</button></div>`});el("shopItems").innerHTML=html}

function renderSmith(subtab){S._smithTab=subtab;document.querySelectorAll(".smith-tab").forEach(b=>b.classList.remove("active"));const btn=document.querySelector(`.smith-tab[data-smith="${subtab}"]`);if(btn)btn.classList.add("active");document.querySelectorAll(".smith-content").forEach(p=>p.classList.remove("active"));const panel=document.getElementById("smith-"+subtab);if(panel)panel.classList.add("active");el("identifyBadge").textContent=S.inventory.filter(i=>i.unidentified).length>0?`(${S.inventory.filter(i=>i.unidentified).length})`:"";const smithMul=S.hero.race==="dwarf"?0.7:1;let sellHtml="";if(S.inventory.length===0)sellHtml=`<div style="color:var(--muted);text-align:center;padding:20px;">没有可出售的物品</div>`;else S.inventory.forEach((item,i)=>{sellHtml+=`<div class="sell-row"><span class="${'rarity-'+item.rarity}">${item.unidentified?'🔍 ':''}${item.name} ${item.type!=="material"?`[${Math.round(item.durability)}/${item.maxDurability}]`:''}</span><span class="sell-price">${item.sellPrice}金</span><button class="small" style="border-color:var(--candle);color:var(--candle);" onclick="sellItem(${i})">出售</button></div>`});el("smith-sell").innerHTML=sellHtml;let idHtml="";const unidItems=S.inventory.filter(i=>i.unidentified);if(unidItems.length===0)idHtml=`<div style="color:var(--muted);text-align:center;padding:20px;">没有待鉴定的物品<br><span style="font-size:10px;">深渊中偶尔能发现需要鉴定的装备</span></div>`;else unidItems.forEach(item=>{const cost=Math.round((item.sellPrice||10)*0.4*smithMul);idHtml+=`<div class="sell-row"><span>🔍 ${item.name}</span><span class="sell-price">鉴定费 ${cost}金</span><button class="small primary" onclick="identifyItem('${item.id}')">鉴定</button></div>`});el("smith-identify").innerHTML=idHtml;let craftHtml=`<table class="craft-table"><tr><th>名称</th><th>类型</th><th>稀有度</th><th>材料</th><th>金币</th><th></th></tr>`;CRAFT_RECIPES.forEach(recipe=>{const locked=!S.unlockedLayers.includes(recipe.needLayer);const resultTpl=EQUIP_TEMPLATES.find(e=>e.id===recipe.result.tid);const name=resultTpl?resultTpl.name:recipe.name;const rarity=resultTpl?resultTpl.rarity:"common";const type=resultTpl?resultTpl.type:"?";const matsText=recipe.materials.map(m=>`${getMaterialName(m.mid)}×${m.qty}`).join(" + ");const craftCost=Math.round(recipe.cost*smithMul);const canCraft=!locked&&recipe.materials.every(m=>countMaterial(m.mid)>=m.qty)&&S.gold>=craftCost&&S.inventory.length<getBagCapacity();craftHtml+=`<tr class="${locked?'locked-row':''}"><td class="${'rarity-'+rarity}">${name}</td><td>${slotLabel(type)}</td><td>${RARITY[rarity]?RARITY[rarity].name:'?'}</td><td>${matsText}</td><td>${craftCost}金${smithMul<1?' (-30%)':''}</td><td>${locked?`<span style="font-size:10px;color:var(--muted);">需要${LAYERS[recipe.needLayer].name}</span>`:`<button class="small primary" ${!canCraft?'disabled':''} onclick="craftItem('${recipe.id}')">打造</button>`}</td></tr>`});craftHtml+=`</table>`;el("smith-craft").innerHTML=craftHtml}

function renderAbyssGate(){let html="";LAYERS.forEach((layer,i)=>{const unlocked=S.unlockedLayers.includes(i);const selected=S.selectedLayer===i;html+=`<div class="layer-card ${unlocked?'':'locked'} ${selected?'selected':''}" ${unlocked?`onclick="selectLayer(${i})"`:''}><div class="l-name">${unlocked?'🔓':'🔒'} ${layer.name}</div><div class="l-depth">${layer.startDepth} - ${layer.maxDepth>=999?'∞':layer.maxDepth} 尺</div><div class="l-monsters">🐉 ${layer.monsters.slice(0,3).join(' · ')}${layer.monsters.length>3?' …':''}</div><div class="l-danger">危险等级：${layer.danger}</div>${!unlocked?`<div class="l-unlock">${layer.unlockMsg||'?'}</div>`:''}${layer.unlockBonus?`<div class="l-unlock" style="color:var(--candle-dim);">${layer.unlockBonus}</div>`:''}</div>`});el("layerCards").innerHTML=html;const layer=LAYERS[S.selectedLayer];const unlocked=S.unlockedLayers.includes(S.selectedLayer);el("abyssAction").innerHTML=unlocked?`<button class="primary" style="font-size:16px;padding:12px 40px;" onclick="startExpedition(${S.selectedLayer})">⚔️ 从「${layer.name}」出征</button>`:`<span style="color:var(--muted);">该层级尚未解锁</span>`}

function renderChurch(){const now=Date.now();const onCooldown=S.prayerCooldown>now;const remaining=onCooldown?S.prayerCooldown-now:0;const hrs=Math.floor(remaining/3600000);const mins=Math.floor((remaining%3600000)/60000);if(S.activeBlessing){el("churchStatus").innerHTML=`<span style="color:var(--candle);">当前祝福生效中：</span>`;el("churchBuff").innerHTML=`<span style="font-size:18px;">${S.activeBlessing.icon} <strong style="color:var(--candle);">${S.activeBlessing.name}</strong></span><br><span style="font-size:12px;color:var(--muted);">${S.activeBlessing.desc}（下次远征生效）</span>`;el("prayBtn").disabled=true;el("prayBtn").textContent="祝福已就绪，出征吧"}else if(onCooldown){el("churchStatus").innerHTML=`<span style="color:var(--muted);">祷告后需静候神明的回应……</span>`;el("churchBuff").innerHTML=`<span style="font-size:13px;color:var(--muted);">冷却剩余：</span><span style="font-size:16px;color:var(--sanity);">${hrs}时${mins}分</span>`;el("prayBtn").disabled=true;el("prayBtn").textContent=`⏳ ${hrs}时${mins}分后可祈祷`}else{el("churchStatus").innerHTML=`<span style="color:var(--muted);">在深渊礼拜堂中静心祈祷，祈求神明的眷顾。</span>`;el("churchBuff").innerHTML=`<span style="font-size:12px;color:var(--muted);">可能获得的祝福：</span><br><span style="font-size:11px;color:var(--muted);">${BLESSINGS.map(b=>b.icon+b.name).join(' · ')}</span>`;el("prayBtn").disabled=false;el("prayBtn").textContent="🕯️ 祈 祷"}const s=calcHeroStats();const effMax=S.hero.maxSanity+s.maxSanityBonus;const cost=Math.ceil((effMax-S.hero.sanity)*1.5);const canRestore=S.hero.sanity<effMax&&S.gold>=cost;el("churchRestore").innerHTML=`<span style="font-size:12px;color:var(--muted);">恢复神智 · ${S.hero.sanity>=effMax?'神智已满':cost+' 金'}</span>`;const rstBtn=document.getElementById("restoreSanityBtn");if(rstBtn){rstBtn.disabled=!canRestore;rstBtn.textContent=S.hero.sanity>=effMax?"🙏 神智已满":`🙏 静心祈祷 · ${cost}金`}}
function doPray(){if(S.prayerCooldown>Date.now()||S.activeBlessing)return;const b=BLESSINGS[Math.floor(Math.random()*BLESSINGS.length)];S.activeBlessing={type:b.id,name:b.name,desc:b.desc,icon:b.icon,apply:b.apply};S.prayerCooldown=Date.now()+3*60*60*1000;pushLog(`⛪ 你在礼拜堂中虔诚祈祷，获得了「${b.name}」——${b.desc}`,"good");render();save()}
function restoreSanity(){const s=calcHeroStats();const effMax=S.hero.maxSanity+s.maxSanityBonus;const cost=Math.ceil((effMax-S.hero.sanity)*1.5);if(S.hero.sanity>=effMax||S.gold<cost)return;S.gold-=cost;S.hero.sanity=effMax;pushLog("你在残烛前静坐良久，心神渐渐安定。","good");render();save()}

function warehouseUpgradeCost(){const level=(S.warehouseSlots-20)/5;return Math.round(100*Math.pow(1.5,level))}
function upgradeWarehouse(){if(S.warehouseSlots>=50)return;const cost=warehouseUpgradeCost();if(S.gold<cost)return;S.gold-=cost;S.warehouseSlots+=5;pushLog(`📦 秘库扩容至 ${S.warehouseSlots} 格，花费 ${cost} 金。`,"good");render();save()}
function depositItem(idx){const item=S.inventory[idx];if(!item||item.unidentified||S.warehouse.length>=S.warehouseSlots)return;if(item.type==="material"&&item.templateId){const existing=S.warehouse.find(w=>w.templateId===item.templateId);if(existing&&existing.qty!==undefined){existing.qty+=1;S.inventory.splice(idx,1);render();save();return}S.warehouse.push({...item,qty:1})}else S.warehouse.push(item);S.inventory.splice(idx,1);render();save()}
function withdrawItem(whIdx){const item=S.warehouse[whIdx];if(!item||S.inventory.length>=getBagCapacity())return;if(item.qty!==undefined&&item.qty>1){const single={...item};delete single.qty;S.inventory.push(single);item.qty-=1;if(item.qty<=0)S.warehouse.splice(whIdx,1)}else{S.inventory.push(item);S.warehouse.splice(whIdx,1)}render();save()}
function renderWarehouse(){const wh=S.warehouse,inv=S.inventory;el("whCount").textContent=wh.length+"/"+S.warehouseSlots;if(S.warehouseSlots>=50)el("whUpgradeRow").innerHTML=`<span style="font-size:11px;color:var(--candle-dim);">秘库已满级 (50格)</span>`;else{const cost=warehouseUpgradeCost();el("whUpgradeRow").innerHTML=`<button class="small" ${S.gold<cost?'disabled':''} onclick="upgradeWarehouse()">扩容 +5格 · ${cost}金</button>`}if(wh.length===0)el("whPanel").innerHTML=`<div style="color:var(--muted);font-size:11px;text-align:center;padding:16px;">仓库空空如也</div>`;else el("whPanel").innerHTML=wh.map((item,i)=>{const name=item.name+(item.qty>1?` ×${item.qty}`:"");const sub=item.type!=="material"?`<span class="inv-dur">${Math.round(item.durability)}/${item.maxDurability}</span>`:"";return `<div class="inv-row"><span class="inv-name ${'rarity-'+item.rarity}">${name}</span>${sub}<span class="inv-act"><button class="small" onclick="withdrawItem(${i})">取出</button></span></div>`}).join("");if(inv.length===0)el("whInvPanel").innerHTML=`<div style="color:var(--muted);font-size:11px;text-align:center;padding:12px;">背包空空如也</div>`;else el("whInvPanel").innerHTML=inv.map((item,i)=>{const canDeposit=!item.unidentified&&wh.length<S.warehouseSlots;return `<div class="inv-row"><span class="inv-name ${'rarity-'+item.rarity}">${item.unidentified?'🔍 ':''}${item.name}</span><span class="inv-dur">${item.type!=="material"?Math.round(item.durability)+'/'+item.maxDurability:''}</span><span class="inv-act"><button class="small" ${!canDeposit?'disabled':''} onclick="depositItem(${i})">${item.unidentified?'🔍鉴定后':'存入'}</button></span></div>`}).join("")}

function confirmDeleteSave(){showModal("确认删除存档","此操作将永久删除你的所有进度，包括金币、装备、怪物志和最深记录。此操作不可撤销。",[{label:"取消",cls:"",action:"hideModal()"},{label:"确认删除",cls:"danger",action:"deleteSave()"}])}
function deleteSave(){S._deleting=true;localStorage.removeItem(SAVE_KEY);hideModal();location.reload()}
function renderSettings(){const el2=document.getElementById("settingsStats");if(el2)el2.innerHTML=`最深记录：<span style="color:var(--candle);">${S.maxDepthRecord.toFixed(1)}</span> 尺<br>持有金币：<span style="color:var(--candle);">${S.gold}</span><br>怪物志：<span style="color:var(--candle);">${Object.keys(S.bestiary).length}</span> 种<br>遗物收集：<span style="color:var(--candle);">${Object.keys(S.relicsOwned).length}</span> / ${RELICS.length}<br>最深层级：<span style="color:var(--candle);">${S.unlockedLayers.length>0?LAYERS[Math.max(...S.unlockedLayers)].name:'浅层回廊'}</span><br>当前种族：<span style="color:var(--candle);">${({human:'👤 人类',elf:'🧝 精灵',bear:'🐻 熊人',dwarf:'⛏️ 矮人'})[S.hero.race]||'???'}</span>`}

function renderTavern(){el("tavernRecord").textContent=S.maxDepthRecord.toFixed(1)}

function renderExpedition(){const ex=S.expedition,stats=calcHeroStats(),h=S.hero;const raceNames={human:"👤 人类",elf:"🧝 精灵",bear:"🐻 熊人",dwarf:"⛏️ 矮人"};el("expRace").textContent=raceNames[h.race]||"👤 人类";el("expLayerName").textContent=LAYERS[ex.layerIndex]?LAYERS[ex.layerIndex].name:"???";el("expCarriedGold").textContent=ex.carriedGold||0;el("hpNum").textContent=`${Math.max(0,Math.round(h.hp))} / ${stats.maxHp}`;el("hpFill").style.width=Math.max(0,(h.hp/stats.maxHp*100))+"%";el("atkNum").textContent=stats.atk;el("defNum").textContent=stats.def;el("dodgeNum").textContent=Math.round(stats.dodge*100)+"%";el("sanityNum").textContent=Math.round(h.sanity)+"/"+(h.maxSanity+stats.maxSanityBonus);el("sanityFill").style.width=(h.sanity/(h.maxSanity+stats.maxSanityBonus)*100)+"%";el("goldNumH").textContent=S.gold;el("depthNum").textContent=ex.depth.toFixed(1);el("recordNum").textContent=S.maxDepthRecord.toFixed(1);const torchPct=ex.active?Math.max(0,ex.torch/ex.maxTorch*100):100;el("torchFill").style.height=torchPct+"%";el("torchPct").textContent=Math.round(torchPct);const flame=el("flame");flame.style.animationDuration=ex.active?(0.6+torchPct/100*1.2)+"s":"1.6s";flame.style.opacity=ex.active?(0.4+torchPct/100*0.6):1;el("expLayerLabel").textContent=LAYERS[ex.layerIndex]?LAYERS[ex.layerIndex].name:"???";el("expDepthMax").textContent=LAYERS[ex.layerIndex]?LAYERS[ex.layerIndex].maxDepth+"尺":"?";if(ex.itemsFound.length===0)el("expItemsBag").innerHTML=`<div style="color:var(--muted);font-size:10px;text-align:center;">暂无战利品</div>`;else el("expItemsBag").innerHTML=ex.itemsFound.map(item=>`<div class="row"><span class="${'rarity-'+item.rarity}">${item.name}</span></div>`).join("");const box=el("encounterBox");if(!ex.active){box.className="encounter empty";box.innerHTML="远征结束"}else if(!ex.monster){if(ex.event&&ex.event.type!=="narrative"){const ev=ex.event;box.className="encounter";box.innerHTML=`<div style="font-size:15px;color:var(--candle);margin-bottom:8px;">${ev.name||"……"}</div><div style="font-size:12px;color:var(--muted);margin-bottom:12px;">${ev.type==="curio"?"一件奇物出现在你面前。":ev.type==="trap"?"前方有危险的气息。":"一处可以歇脚的地方。"}</div><div style="display:flex;gap:8px;"><button class="small" onclick="resolveEvent('safe')" style="flex:1;">${ev.safe.text||"稳妥行事"}</button><button class="small danger" onclick="resolveEvent('risky')" style="flex:1;">${ev.risky.text||"冒险一试"}</button></div>`}else{box.className="encounter empty";box.innerHTML="回廊寂静无声…"}}else{box.className="encounter";const pct=Math.max(0,ex.monster.hp/ex.monster.maxHp*100);box.innerHTML=`<div class="monster-name">${ex.monster.name}</div><div class="monster-hp-wrap"><div class="monster-hp"><div style="width:${pct}%"></div></div><div class="monster-hp-num">${Math.max(0,Math.round(ex.monster.hp))}/${ex.monster.maxHp}</div></div>`}el("descendBtn").disabled=ex.active;el("retreatBtn").disabled=!ex.active;el("logBox").innerHTML=S.logs.map(l=>`<div class="entry ${l.cls}">${l.text}</div>`).join("");const skillBar=document.getElementById("skillBar");if(skillBar){const bloodrageBlock=h.race==="bear"&&h.sanity<h.maxSanity*0.3;const allSkills=[...SKILLS.filter(s=>!s.race||s.race===h.race)];skillBar.innerHTML=allSkills.map(sk=>{const onCd=ex.skillCooldowns[sk.id]&&ex.skillCooldowns[sk.id]>0;const cdText=onCd?` (${ex.skillCooldowns[sk.id]}s)`:"";let disabled=!ex.active||!ex.monster||bloodrageBlock;if(ex.active&&ex.monster&&!onCd&&!bloodrageBlock){if(sk.costType==="sanity"&&h.sanity<sk.cost)disabled=true;if(sk.costType==="torch"&&ex.torch<sk.cost)disabled=true;if(sk.costType==="hp"&&h.hp<=sk.cost)disabled=true}let cls="skill-btn";if(onCd)cls+=" on-cooldown";const hasBuff=ex.activeBuffs[sk.buffKey];if(hasBuff)cls+=" active-buff";if(sk.id==="allin")cls+=" danger";const text=onCd?sk.name+cdText:sk.name;return `<button class="${cls}" ${disabled?'disabled':''} onclick="useSkill('${sk.id}')">${sk.name}</button>`}).join("")}const consumableBar=document.getElementById("consumableBar");if(consumableBar){const inCombat=ex.active&&ex.monster;consumableBar.innerHTML=SHOP_ITEMS.map(item=>{const held=ex.consumables[item.id]||0;const combatOnly=(item.effect==="holyWater"||item.effect==="firebomb");const canUse=ex.active&&held>0&&(!combatOnly||inCombat);return `<button class="skill-btn" ${!canUse?'disabled':''} onclick="useConsumable('${item.id}')" title="${item.desc} (剩余 ${held})">${item.icon} ${held}</button>`}).join("")}document.getElementById("headerEyebrow").textContent="深 渊 · 探 索 · 生 存";document.getElementById("headerSub").textContent="火光摇曳，深渊在等待"}

function equipFromInv(idx){const item=S.inventory[idx];if(!item||item.unidentified||item.type==="material")return;const slotKey=item.type;if(!S.equipment.hasOwnProperty(slotKey))return;const unlockMap={weapon:1,body:1,hands:2,feet:3,head:5,waist:6,cloak:7,relic:8};if(S.equipSlots<(unlockMap[slotKey]||1))return;const old=S.equipment[slotKey];S.equipment[slotKey]=item;if(old){if(S.inventory.length>=getBagCapacity()){S.gold+=Math.floor(old.sellPrice||1);pushLog(`背包已满，换下的${old.name}自动出售。`,"dim")}else{S.inventory.splice(idx,1,old);pushLog(`将${old.name}换为${item.name}。`,"dim")}}else{S.inventory.splice(idx,1);pushLog(`装备了${item.name}。`,"dim")}render();save()}
function unequipItem(slotKey){const item=S.equipment[slotKey];if(!item)return;if(S.inventory.length>=getBagCapacity()){S.gold+=Math.floor(item.sellPrice||1);S.equipment[slotKey]=null;pushLog(`背包已满，卸下${item.name}后自动出售，获得 ${Math.floor(item.sellPrice||1)} 金。`,"dim")}else{S.inventory.push(item);S.equipment[slotKey]=null;pushLog(`卸下了${item.name}。`,"dim")}render();save()}
function repairEquipment(slotKey){const item=S.equipment[slotKey];const cost=repairCost(item);if(cost<=0||S.gold<cost)return;S.gold-=cost;item.durability=item.maxDurability;pushLog(`修复了${item.name}，花费 ${cost} 金。`,"dim");render();save()}
function sellItem(idx){const item=S.inventory[idx];if(!item)return;S.gold+=item.sellPrice||1;pushLog(`出售了${item.name}，获得 ${item.sellPrice||1} 金。`,"dim");S.inventory.splice(idx,1);render();save()}
function discardItem(idx){S.inventory.splice(idx,1);pushLog("丢弃了一件物品。","dim");render();save()}
function identifyItem(itemId){const item=S.inventory.find(i=>i.id===itemId);if(!item||!item.unidentified)return;const smithMul=S.hero.race==="dwarf"?0.7:1;const cost=Math.round((item.sellPrice||10)*0.4*smithMul);if(S.gold<cost){pushLog("金币不足，无法鉴定。","warn");render();save();return}S.gold-=cost;item.unidentified=false;if(item.templateId){const tpl=EQUIP_TEMPLATES.find(e=>e.id===item.templateId);if(tpl)item.name=tpl.name}pushLog(`鉴定完成——是「${item.name}」！`,"good");render();save()}
function craftItem(recipeId){const recipe=CRAFT_RECIPES.find(r=>r.id===recipeId);if(!recipe||!S.unlockedLayers.includes(recipe.needLayer))return;if(!recipe.materials.every(m=>countMaterial(m.mid)>=m.qty))return;const smithMul=S.hero.race==="dwarf"?0.7:1;const craftCost=Math.round(recipe.cost*smithMul);if(S.gold<craftCost||S.inventory.length>=getBagCapacity())return;recipe.materials.forEach(m=>{let q=S.hero.race==="dwarf"?Math.max(1,m.qty-1):m.qty;while(q>0){const idx=S.inventory.findLastIndex(i=>i.templateId===m.mid);if(idx>=0){S.inventory.splice(idx,1);q--}else break}});S.gold-=craftCost;const tpl=EQUIP_TEMPLATES.find(e=>e.id===recipe.result.tid);if(tpl){const item={id:tpl.id+"_craft_"+Date.now()+"_"+Math.random().toString(36).slice(2,6),templateId:tpl.id,name:tpl.name,type:tpl.type,rarity:tpl.rarity,stats:{...tpl.baseStats},durability:tpl.baseDura,maxDurability:tpl.baseDura,sellPrice:tpl.baseVal,unidentified:false};S.inventory.push(item);pushLog(`打造完成——获得「${item.name}」！`,"good");S.craftsMade=(S.craftsMade||0)+1;if(S.craftsMade>=3)unlockRace("dwarf")}render();save()}
